insert into public.articles (id,title,brief,category,minutes,author,reviewer,date,cover,thumb,body,refs,featured,published) values
('a1','اضطراب چیست؟ علائم، علت‌ها و ۷ راه آرام کردن ذهن','شب است و همه خواب‌اند، اما ذهن شما تازه بیدار شده. فردا جلسه دارید، قسط وام عقب افتاده، و صدای تپش قلبتان را در گوش می‌شنوید. چند بار غلت می‌زنید و به خودتان می‌گویید «چیزی نیست»، اما بدنتان حرف دیگری می‌زند. اگر این صحنه برایتان آشناست، احتمالاً با علائم اضطراب از نزدیک آشنا هستید.','mental',8,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۱','img/articles/a1-cover.jpg','img/articles/a1-thumb.jpg','<p>اضطراب تجربه‌ای همگانی است، اما وقتی زیاد و طولانی شود، کیفیت زندگی را می‌بلعد. در این مقاله می‌بینیم اضطراب چیست، چه نشانه‌هایی دارد، چه وقت از حد طبیعی می‌گذرد، و چه کارهایی از همین امروز به آرام‌تر شدن ذهن کمک می‌کند.</p><h2>قصه‌ی نیلوفر: ترسی که در مترو جا ماند</h2><p>نیلوفر بیست‌وهشت سال دارد و کارمند شعبه‌ی مرکزی یک بانک است. آدمی دقیق و مسئولیت‌پذیر که همکارانش همیشه کارهای حساس را به او می‌سپارند. پارسال، فصل بستن حساب‌های آخر سال، هفته‌ها تا دیروقت کار کرده بود. یک روز صبح، در متروی شلوغ، ناگهان قلبش شروع کرد به کوبیدن. نفسش بالا نمی‌آمد، دست‌هایش یخ کرده بود و حس می‌کرد همین حالا از حال می‌رود. در ایستگاه بعد خودش را بیرون انداخت و روی نیمکت نشست. مطمئن بود سکته کرده.</p><p>در اورژانس، نوار قلب و آزمایش‌ها سالم بود. پزشک گفت «احتمالاً اضطراب است» و مرخصش کرد. نیلوفر خیالش راحت نشد. فکر می‌کرد: «اگر دوباره بیاید؟ اگر این بار واقعاً چیزی باشد؟» از فردای آن روز دیگر سوار مترو نشد. صبح‌ها یک ساعت زودتر از خانه بیرون می‌زد تا با تاکسی برود، و هر بار که ترافیک می‌شد، دلشوره می‌گرفت که دیر برسد.</p><p>چند ماه بعد، دامنه‌ی ترس بزرگ‌تر شده بود. در جلسه‌های شلوغ کاری، جای نزدیک در را انتخاب می‌کرد. به عروسی دخترخاله‌اش نرفت، چون سالن بزرگ و پرجمعیت بود. شب‌ها ساعت‌ها فکر می‌کرد که فردا چه چیزی ممکن است خراب شود: گزارش، جلسه، سلامتی پدرش. صبح‌ها با گردن خشک و فک منقبض بیدار می‌شد و دندان‌پزشکش گفته بود شب‌ها دندان‌هایش را به هم می‌فشارد. همکارش گفت «تو همیشه نگرانی»، و نیلوفر برای اولین بار فکر کرد شاید حق با اوست.</p><p>بدتر از همه، حس می‌کرد کنترل زندگی‌اش از دستش رفته. می‌دانست ترس‌هایش منطقی نیست، اما بدنش به حرف منطق گوش نمی‌داد. هر بار که به قلبش توجه می‌کرد، ضربانش تندتر می‌شد، و همین تندتر شدن ترسش را بیشتر می‌کرد. یک شب، بعد از اینکه برای سومین بار در یک هفته از ترس تپش قلب بیدار شد، در اینترنت جستجو کرد: «چرا بی‌دلیل می‌ترسم؟» فردای آن روز، برای اولین بار به خودش اجازه داد قبول کند که شاید مشکل قلبش نیست؛ شاید ذهنش است که بیش از حد از او محافظت می‌کند.</p><h2>از کجا بفهمم اضطرابم از حد طبیعی گذشته؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند تجربه‌ی خودتان را روشن‌تر ببینید. اگر به چند مورد پاسخ «بله» دادید، صحبت با یک متخصص می‌تواند مفید باشد.</p><ol><li>آیا بیشتر روزها نگرانی‌ای دارید که کنترلش برایتان سخت است؟</li><li>آیا اغلب بی‌قرار یا «روی لبه» هستید؟</li><li>آیا زود خسته می‌شوید، حتی وقتی کار زیادی نکرده‌اید؟</li><li>آیا تمرکز کردن برایتان سخت شده یا ذهنتان گاهی خالی می‌شود؟</li><li>آیا عضلاتتان، مثلاً گردن و شانه، بیشتر وقت‌ها منقبض است؟</li><li>آیا به‌خاطر نگرانی، خوابتان به هم ریخته است؟</li><li>آیا از موقعیت‌هایی دوری می‌کنید چون می‌ترسید دوباره دچار تپش قلب یا ترس شدید شوید؟</li></ol><h2>اضطراب چیست و چرا پیش می‌آید؟</h2><p>اضطراب در اصل سیستم هشدار بدن است. وقتی مغز خطری را پیش‌بینی می‌کند، بدن را برای «جنگ یا گریز» آماده می‌کند: قلب تندتر می‌زند، عضلات منقبض می‌شوند و ذهن روی خطر متمرکز می‌شود. این واکنش در موقعیت واقعی، مثلاً وقتی ماشینی با سرعت به سمتتان می‌آید، جانتان را نجات می‌دهد.</p><p>مشکل زمانی شروع می‌شود که این هشدار بی‌وقفه یا بی‌دلیل روشن بماند. سازمان جهانی بهداشت اختلال‌های اضطرابی را شایع‌ترین اختلال‌های روانی جهان می‌داند و برآورد می‌کند حدود ۵.۸ درصد مردم جهان در حال حاضر با یکی از آن‌ها زندگی می‌کنند. با این حال، تنها حدود یک نفر از هر چهار نفر درمان دریافت می‌کند.</p><p>عوامل مؤثر معمولاً ترکیبی‌اند:</p><ul><li>زمینه‌ی ارثی و خلق‌وخو: بعضی از ما از کودکی حساس‌تر و نگران‌تریم.</li><li>استرس‌های طولانی: فشار مالی، شغلی یا خانوادگی.</li><li>تجربه‌های سخت گذشته: حادثه، فقدان یا محیط ناامن در کودکی.</li><li>الگوهای فکری: فاجعه‌سازی، یعنی همیشه بدترین سناریو را محتمل‌ترین دانستن.</li></ul><h2>علائم اضطراب: ذهن، بدن و رفتار</h2><p>اضطراب فقط «نگرانی» نیست. در سه سطح خودش را نشان می‌دهد:</p><h2>در ذهن</h2><ul><li>نگرانی مداوم که کنترلش سخت است</li><li>احساس اینکه «اتفاق بدی در راه است»</li><li>مشکل در تمرکز و ذهنی که «خالی» می‌شود</li></ul><h2>در بدن</h2><ul><li>تپش قلب، تنگی نفس یا احساس خفگی</li><li>تنش عضلانی، به‌خصوص در گردن و شانه</li><li>دل‌درد، تهوع، سرگیجه و تعریق</li><li>خستگی و خواب آشفته</li></ul><h2>در رفتار</h2><ul><li>دوری از موقعیت‌هایی که ترس را برمی‌انگیزند</li><li>اطمینان‌طلبی مکرر، مثلاً بارها پرسیدن «مطمئنی اتفاقی نمی‌افتد؟»</li><li>زودرنجی و بی‌قراری</li></ul><p>اختلال‌های اضطرابی انواع مختلفی دارند: اضطراب فراگیر، حمله‌ی پانیک، اضطراب اجتماعی، فوبیاها و اضطراب جدایی. هرکدام نشانه‌های خاص خود را دارند، اما هسته‌ی مشترکشان ترسی است که بزرگ‌تر از خطر واقعی است.</p><h2>۷ راه برای آرام کردن ذهن مضطرب</h2><ol><li>تنفس آرام را تمرین کنید. وقتی مضطربیم، نفس‌ها کوتاه و سطحی می‌شوند. چهار ثانیه دم، دو ثانیه مکث و شش ثانیه بازدم را چند دقیقه تکرار کنید. بازدمِ طولانی‌تر به بدن پیام امنیت می‌دهد.</li><li>نگرانی را روی کاغذ بیاورید. روزی پانزده دقیقه را «وقت نگرانی» بگذارید و همه‌ی نگرانی‌ها را بنویسید. بیرون از این زمان، وقتی فکری آمد، به خودتان بگویید «بعداً به آن فکر می‌کنم».</li><li>از اجتناب دست بکشید، اما قدم‌به‌قدم. دوری از موقعیت ترسناک در لحظه آرامتان می‌کند، اما ترس را در درازمدت بزرگ‌تر می‌کند. نردبانی از موقعیت‌ها بسازید، از آسان به سخت، و پله‌پله جلو بروید.</li><li>فکرها را محک بزنید. بپرسید: «احتمال واقعی این اتفاق چقدر است؟ اگر هم بیفتد، از پسش برمی‌آیم؟» ذهن مضطرب احتمال را بزرگ و توانایی ما را کوچک می‌بیند.</li><li>بدن را حرکت دهید. پیاده‌روی تند، دوچرخه یا هر ورزشی که دوست دارید، انرژی جمع‌شده‌ی اضطراب را تخلیه می‌کند.</li><li>کافئین و صفحه‌ی گوشی را کم کنید. قهوه‌ی زیاد علائم جسمی اضطراب را تشدید می‌کند. اخبار پیاپی هم سیستم هشدار مغز را دائم روشن نگه می‌دارد.</li><li>با کسی حرف بزنید. گفتن نگرانی به یک آدم مطمئن، اغلب از شدتش می‌کاهد.</li></ol><p>برگردیم به نیلوفر. با کمک درمانگرش اول فقط تا ایستگاه رفت، بعد یک ایستگاه سوار شد، و چند هفته بعد کل مسیر را رفت. ترس یک‌شبه نرفت، اما هر قدم به او ثابت کرد بدنش بیش از آنچه فکر می‌کرد تاب می‌آورد.</p><p>نیلوفر بعدها در جلسه‌ای گفت سخت‌ترین بخش ماجرا، ترس از خودِ ترس بود. هر بار که سوار می‌شد، منتظر بود قلبش تند بزند، و همین انتظار، تپش را شروع می‌کرد. درمانگرش از او خواست به‌جای جنگیدن با تپش قلب، فقط آن را توصیف کند: «قلبم تند می‌زند، دست‌هایم عرق کرده، و این‌ها خطرناک نیستند.» در هفته‌ی چهارم، وسط مسیر، حس کرد موج اضطراب آمد، به اوج رسید و چند دقیقه بعد فروکش کرد، بدون اینکه پیاده شود. همان روز برای اولین بار فهمید اضطراب، هرچقدر هم شدید، موجی است که می‌آید و می‌رود.</p><h2>باورهای نادرست رایج درباره‌ی اضطراب</h2><p>«اضطراب یعنی ضعف شخصیت.» نه. اضطراب واکنش یک سیستم زیستی است که بیش از حد حساس شده، نه نشانه‌ی کم بودن اراده یا ایمان. آدم‌های بسیار توانمند هم با اضطراب زندگی می‌کنند.</p><p>«باید از موقعیت‌های ترسناک دوری کنم تا حالم بهتر شود.» دوری کردن در لحظه آرامش می‌آورد، اما به مغز یاد می‌دهد که آن موقعیت واقعاً خطرناک بوده. برای همین ترس دفعه‌ی بعد بزرگ‌تر برمی‌گردد. راه بهبود، رویارویی تدریجی و امن است.</p><p>«اگر به نگرانی‌ام فکر نکنم، اتفاق بدی می‌افتد.» بسیاری از آدم‌های مضطرب ناخودآگاه باور دارند نگرانی از آن‌ها محافظت می‌کند. اما نگرانی معمولاً به‌جای آماده کردن، فقط فرسوده می‌کند. برنامه‌ریزی با نگرانی فرق دارد: برنامه‌ریزی به عمل ختم می‌شود، نگرانی به چرخیدن دور خود.</p><p>«داروی اعصاب یعنی وابستگی همیشگی.» تصمیم درباره‌ی دارو با روان‌پزشک است و همه‌ی داروها اعتیادآور نیستند. برای بسیاری از افراد، روان‌درمانی به‌تنهایی کافی است و برای برخی ترکیب این دو بهترین نتیجه را می‌دهد.</p><p>«اضطراب هیچ‌وقت تمام نمی‌شود.» اضطراب به‌عنوان یک احساس طبیعی همیشه بخشی از زندگی است، اما اختلال اضطرابی قابل درمان است و بیشتر افراد با کمک مناسب به زندگی آرام‌تری برمی‌گردند.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر اضطراب بیشتر روزها با شماست، خواب یا کار یا رابطه‌هایتان را مختل کرده، یا به خاطرش از کارهای مهم دوری می‌کنید، وقت مشورت با روان‌شناس است. روان‌درمانی، به‌ویژه درمان‌های رفتاری‌شناختی، برای بیشتر انواع اضطراب اثربخشی ثابت‌شده دارد و گاهی در کنار دارو به کار می‌رود. اگر حمله‌ی تپش قلب و تنگی نفس برای اولین بار رخ داده، اول به پزشک مراجعه کنید تا علت جسمی کنار گذاشته شود. برای مشاوره، با مرکز مشاوره‌ی انتخاب بهتر به شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>فرق استرس و اضطراب چیست؟</h3><p>استرس معمولاً واکنش به یک فشار مشخص و بیرونی است و با رفع آن کم می‌شود. اضطراب می‌تواند بدون محرک روشن ادامه پیدا کند و بیشتر درباره‌ی آینده است.</p><h3>آیا اضطراب درمان قطعی دارد؟</h3><p>بیشتر افراد با درمان مناسب بهبود چشمگیری پیدا می‌کنند. هدف درمان صفر کردن اضطراب نیست؛ این است که اضطراب دیگر زندگی شما را اداره نکند.</p><h3>آیا اضطراب می‌تواند علائم جسمی واقعی ایجاد کند؟</h3><p>بله. تپش قلب، سردرد، دل‌درد و تنگی نفس از علائم رایج اضطراب‌اند و واقعی‌اند، حتی وقتی آزمایش‌ها سالم باشند.</p><h2>جمع‌بندی</h2><p>اضطراب دشمن شما نیست؛ زنگ هشداری است که بیش از حد حساس شده. با شناختن علائم اضطراب و تمرین چند مهارت ساده، می‌توانید صدای این زنگ را آرام‌تر کنید. و اگر تنهایی سخت است، کمک گرفتن نشانه‌ی قدرت است، نه ضعف.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/55/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8-%D8%A8%DA%A9---BAI-" target="_blank" rel="noopener">پرسشنامه اضطراب بک (BAI)</a> | <a href="https://www.betterchoice.ir/fa/qdetail/24/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%A7%D8%AE%D8%AA%D9%84%D8%A7%D9%84-%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8-%D9%81%D8%B1%D8%A7%DA%AF%DB%8C%D8%B1" target="_blank" rel="noopener">مقیاس اختلال اضطراب فراگیر</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/566/%D8%B4%DB%8C%D9%88%D9%87-%D9%87%D8%A7%DB%8C-%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA-%D9%87%DB%8C%D8%AC%D8%A7%D9%86%D8%A7%D8%AA-%D9%85%D9%86%D9%81%DB%8C---%D8%AE%D8%B4%D9%85--%D8%AF%D9%84%D9%85%D8%B1%D8%AF%DA%AF%DB%8C--%D8%AD%D8%B3%D8%A7%D8%AF%D8%AA" target="_blank" rel="noopener">شیوه های مدیریت هیجانات منفی ( خشم، دلمردگی، حسادت، شرم، اضطراب)</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6684/%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA_%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8_%D9%87%D9%86%D8%B1_%D8%AF%D8%B1%D8%B3%D8%AA_%D8%A7%D9%86%D8%AF%DB%8C%D8%B4%DB%8C%D8%AF%D9%86" target="_blank" rel="noopener">مدیریت اضطراب؛ هنر درست اندیشیدن</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6746/%D8%A2%D8%B2%D8%A7%D8%AF_%DA%A9%D8%B1%D8%AF%D9%86_%D8%B0%D9%87%D9%86_%D8%A7%D8%B2_%DA%86%D8%B1%D8%AE%D9%87_%D8%A7%D9%81%DA%A9%D8%A7%D8%B1_%D9%85%D9%86%D9%81%DB%8C" target="_blank" rel="noopener">آزاد کردن ذهن از چرخه افکار منفی</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6751/%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA_%D9%87%DB%8C%D8%AC%D8%A7%D9%86%E2%80%8C%D9%87%D8%A7%DB%8C_%D8%B7%D8%A7%D9%82%D8%AA%E2%80%8C%D9%81%D8%B1%D8%B3%D8%A7" target="_blank" rel="noopener">مدیریت هیجان‌های طاقت‌فرسا</a></p></div>','["World Health Organization. Anxiety disorders [Fact sheet]. https://www.who.int/news-room/fact-sheets/detail/anxiety-disorders", "Psych Central. Anxiety disorders: Symptoms, types, and treatments. https://psychcentral.com/anxiety/anxiety-disorders", "Psych Central. Generalized anxiety disorder (GAD) symptoms. https://psychcentral.com/anxiety/generalized-anxiety-disorder-symptoms"]'::jsonb,true,true),
('a2','افزایش اعتماد به نفس: ۱۰ راهکار عملی از نگاه روان‌شناس','در جلسه ایده‌ای دارید، اما تا می‌خواهید حرف بزنید، صدایی در سرتان می‌گوید: «اگر مسخره باشد چه؟» ساکت می‌مانید و چند دقیقه بعد همکارتان همان ایده را می‌گوید و تحسین می‌شود. این صحنه برای خیلی‌ها آشناست. افزایش اعتماد به نفس از پرجستجوترین دغدغه‌های روان‌شناختی است، و دلیلش روشن است: کمبود آن روی کار، رابطه و حال روزمره سایه می‌اندازد.','self',7,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۲','img/articles/a2-cover.jpg','img/articles/a2-thumb.jpg','<p>در این مقاله می‌بینیم اعتماد به نفس واقعاً چیست، چه چیزی آن را تضعیف می‌کند، و چه کارهایی، فراتر از جمله‌های انگیزشی، آن را می‌سازد.</p><h2>قصه‌ی الهام: ایده‌ای که دیگری گفت</h2><p>الهام بیست‌وهفت سال دارد و دانشجوی کارشناسی ارشد روان‌شناسی صنعتی است. باهوش است، کتاب زیاد می‌خواند و استادانش همیشه از مقاله‌هایش تعریف می‌کنند. اما در کلاس، تقریباً هیچ‌وقت حرف نمی‌زند.</p><p>یک روز، در کلاس سمینار، استاد درباره‌ی انگیزه‌ی کارکنان سؤالی پرسید. الهام دقیقاً جواب را می‌دانست؛ همان هفته مقاله‌ای درباره‌اش خوانده بود. دستش را تا نیمه بالا برد، اما صدایی در سرش گفت: «اگر اشتباه بگویی چه؟ همه می‌فهمند که آن‌قدرها هم باهوش نیستی.» دستش را پایین آورد. چند ثانیه بعد، همکلاسی‌اش، کیان، تقریباً همان ایده را گفت و استاد گفت: «عالی بود، کیان!» الهام تا آخر کلاس به میزش خیره ماند.</p><p>این الگو در زندگی‌اش تکرار می‌شد. وقتی دوستانش از او تعریف می‌کردند، می‌گفت: «نه بابا، شانسی بود.» وقتی نمره‌ی بیست می‌گرفت، فکر می‌کرد «حتماً امتحان آسان بود». اما وقتی یک اشتباه کوچک می‌کرد، تا چند روز در ذهنش مرورش می‌کرد. خودش را مدام با بقیه مقایسه می‌کرد: هم‌دوره‌ای‌اش که مقاله چاپ کرده بود، دخترخاله‌اش که کار خوبی پیدا کرده بود، و آدم‌های موفق اینستاگرام.</p><p>بدترین لحظه‌ها، ارائه‌ها بود. شب قبل از هر ارائه خواب نداشت. متن را بارها حفظ می‌کرد، اما جلوی کلاس، صدایش می‌لرزید، دست‌هایش عرق می‌کرد و گاهی جمله‌ها را فراموش می‌کرد. بعد از ارائه، حتی اگر استاد تعریف می‌کرد، الهام فقط به آن دو جمله‌ای فکر می‌کرد که تپق زده بود.</p><p>ترم پیش، فرصت کارآموزی در یک شرکت معتبر پیش آمد. الهام همه‌ی شرایط را داشت، اما درخواست نداد. به خودش گفت: «حتماً آدم‌های بهتری درخواست می‌دهند.» بعدها فهمید که همان کیان درخواست داده و پذیرفته شده است.</p><p>یک شب، بعد از اینکه دوباره در کلاس ساکت مانده بود، به دوستش، ترانه، پیام داد: «خسته شدم از اینکه همیشه خودم را کوچک می‌کنم.» ترانه جواب داد: «الهام، تو باهوش‌ترین آدمی هستی که می‌شناسم. فقط خودت این را باور نمی‌کنی.» الهام آن شب تصمیم گرفت که این بار، به‌جای منتظر ماندن برای اینکه روزی «احساس اعتماد به نفس» بیاید، کاری بکند.</p><h2>آیا اعتماد به نفس پایینی دارم؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند تجربه‌ی خودتان را روشن‌تر ببینید. اگر به چند مورد پاسخ «بله» دادید، صحبت با یک متخصص می‌تواند مفید باشد.</p><ol><li>آیا از ترس قضاوت شدن، نظرتان را در جمع نمی‌گویید؟</li><li>آیا مدام خودتان را با دیگران مقایسه می‌کنید؟</li><li>آیا موفقیت‌هایتان را به شانس نسبت می‌دهید و اشتباه‌هایتان را بزرگ می‌کنید؟</li><li>آیا پذیرفتن تعریف و تمجید برایتان سخت است؟</li><li>آیا از چالش‌ها و فرصت‌های تازه دوری می‌کنید؟</li><li>آیا از ترس ناراحت کردن دیگران، «نه» نمی‌گویید؟</li><li>آیا صدای درونی‌تان بیشتر سرزنشگر است تا مهربان؟</li></ol><h2>اعتماد به نفس و عزت نفس چیست؟</h2><p>این دو واژه اغلب به جای هم به کار می‌روند، اما کمی فرق دارند:</p><ul><li>اعتماد به نفس یعنی باور به توانایی خود در انجام کارها: «از پسش برمی‌آیم.»</li><li>عزت نفس یعنی احساس کلی ارزشمند بودن: «من ارزشمندم، حتی وقتی شکست می‌خورم.»</li></ul><p>اعتماد به نفس معمولاً از تجربه ساخته می‌شود: هر بار که کاری را انجام می‌دهیم که از آن می‌ترسیدیم، شواهد تازه‌ای برای توانایی‌مان جمع می‌شود. عزت نفس بیشتر از رابطه‌ی ما با خودمان تغذیه می‌شود.</p><p>پژوهش‌های کریستین نف، از پیشگامان مطالعه‌ی «شفقت به خود»، نشان داده‌اند کسانی که با خودشان مهربان‌ترند، کمتر دچار اضطراب و افسردگی می‌شوند و بعد از شکست سریع‌تر برمی‌خیزند. یعنی برخلاف تصور رایج، سخت‌گیری بر خود اعتماد به نفس نمی‌سازد؛ مهربانی با خود پایه‌ی محکم‌تری است.</p><h2>نشانه‌های اعتماد به نفس پایین</h2><ul><li>ترس از اظهار نظر و قضاوت شدن</li><li>مقایسه‌ی مداوم خود با دیگران</li><li>نادیده گرفتن موفقیت‌ها و بزرگ کردن اشتباه‌ها</li><li>سخت بودن پذیرش تعریف و تمجید</li><li>اجتناب از چالش‌های تازه</li><li>«نه» نگفتن از ترس ناراحت کردن دیگران</li><li>گفتگوی درونی سرزنشگر</li></ul><h2>۱۰ راهکار عملی برای افزایش اعتماد به نفس</h2><ol><li>قدم‌های کوچک بردارید. اعتماد به نفس از عمل می‌آید، نه از انتظار. هر هفته یک کار کوچک انجام دهید که کمی از آن می‌ترسید، مثل یک سؤال در کلاس.</li><li>دفتر شواهد داشته باشید. هر شب سه کار را که خوب انجام دادید بنویسید، حتی کوچک. ذهن ما به منفی‌ها حساس‌تر است و باید آگاهانه مثبت‌ها را ثبت کرد.</li><li>با صدای سرزنشگر درونی بحث کنید. وقتی گفت «تو بی‌عرضه‌ای»، بپرسید: «اگر دوستم این را درباره‌ی خودش بگوید، چه جوابی می‌دهم؟»</li><li>شفقت به خود را تمرین کنید. بعد از اشتباه، به‌جای سرزنش، بگویید: «اشتباه کردم و این انسانی است. از آن چه یاد می‌گیرم؟» پژوهش‌ها نشان داده‌اند نوشتن نامه‌ای مهربان به خود می‌تواند حال روحی را بهتر کند.</li><li>مقایسه را محدود کنید. شبکه‌های اجتماعی ویترین زندگی دیگران‌اند، نه کل آن. زمان گشت‌وگذار را کم کنید و صفحه‌هایی را که حالتان را بد می‌کنند، دنبال نکنید.</li><li>مهارت بسازید. گاهی کمبود اعتماد به نفس، کمبود مهارت است. یادگیری یک مهارت مشخص، مثل سخنرانی، اعتماد واقعی می‌سازد.</li><li>بدن را جدی بگیرید. فعالیت بدنی منظم با افزایش عزت نفس همراه است. خواب و تغذیه‌ی کافی هم انرژی لازم برای چالش‌ها را می‌دهد.</li><li>«نه» گفتن را تمرین کنید. هر «نه» محترمانه پیامی به خودتان است: «نیازهای من هم مهم‌اند.»</li><li>تعریف را بپذیرید. به‌جای «نه بابا، چیزی نبود»، فقط بگویید «ممنونم.»</li><li>خودتان را با دیروزتان مقایسه کنید. پیشرفت را با معیار خودتان بسنجید، نه با بهترین آدم‌های اطراف.</li></ol><p>برگردیم به الهام. در مشاوره به‌جای «اعتماد به نفس داشته باش»، تمرین‌هایش را مرحله‌بندی کرد: اول برای آینه، بعد برای خواهرش، بعد برای سه دوست. ارائه‌ی کلاسی هنوز استرس داشت، اما این بار می‌دانست بارها از پسش برآمده.</p><p>مهم‌ترین تغییر الهام اما در گفتگوی درونی‌اش بود. عادت داشت بعد از هر ارائه فقط اشتباه‌هایش را مرور کند: «آنجا تپق زدم، آنجا یادم رفت.» مشاورش از او خواست بعد از هر ارائه، اول دو کاری را که خوب انجام داده بنویسد و بعد سراغ اشتباه‌ها برود. اوایل این کار برایش مصنوعی بود. اما بعد از چند هفته تصویر متعادل‌تری از خودش داشت: کسی که گاهی تپق می‌زند، اما مطلبش را خوب می‌شناسد و می‌تواند به سؤال‌ها جواب دهد. ترم بعد، داوطلب شد اولین ارائه‌ی کلاس را انجام دهد؛ کاری که یک سال قبل حتی تصورش را نمی‌کرد.</p><p>یک تمرین برای همین هفته: یک «نردبان جرئت» با پنج پله بسازید: از کار کمی ترسناک تا کار خیلی ترسناک. مثلاً از پرسیدن یک سؤال در جمع شروع کنید تا ارائه‌ی یک پیشنهاد در جلسه. این هفته فقط پله‌ی اول را بالا بروید و بعدش به خودتان تبریک بگویید.</p><h2>باورهای نادرست رایج درباره‌ی اعتماد به نفس</h2><p>«آدم با اعتماد به نفس هیچ‌وقت نمی‌ترسد.» اعتماد به نفس یعنی با وجود ترس، قدم برداشتن. حتی سخنرانان باتجربه هم قبل از اجرا استرس دارند.</p><p>«با تکرار جمله‌های مثبت جلوی آینه، اعتماد به نفس می‌آید.» جمله‌های مثبتی که باورشان نداریم، گاهی حتی اثر معکوس دارند. اعتماد واقعی از تجربه‌ی عملی و شواهد واقعی ساخته می‌شود.</p><p>«سخت‌گیری بر خود باعث پیشرفت می‌شود.» در چهار آزمایش، برینز و چن نشان دادند پذیرفتن مهربانانه‌ی شکست، انگیزه‌ی آدم‌ها را برای جبران اشتباه و بهتر شدن بیشتر می‌کند، نه کمتر.</p><p>«اعتماد به نفس یعنی همیشه حق با من باشد.» آدم با اعتماد به نفس راحت‌تر می‌تواند اشتباهش را بپذیرد، چون ارزشش به درست بودن همیشگی وابسته نیست.</p><p>«اول باید اعتماد به نفس پیدا کنم، بعد کار را شروع کنم.» معمولاً برعکس است. اول کار کوچک را انجام می‌دهیم، و اعتماد به نفس پشت سرش می‌آید.</p><p>«اعتماد به نفس پایین یعنی آدم بی‌عرضه‌ای هستم.» بسیاری از آدم‌های توانمند، توانایی‌های خودشان را دست‌کم می‌گیرند. کمبود اعتماد به نفس اغلب ربطی به توانایی واقعی ندارد.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر احساس بی‌ارزشی عمیق است، با غم مداوم یا اضطراب همراه است، یا ریشه در تجربه‌های تلخ کودکی دارد، کار با روان‌شناس می‌تواند ریشه‌ها را پیدا کند. گاهی کمبود عزت نفس نشانه‌ی افسردگی است. برای مشاوره، با مرکز مشاوره‌ی انتخاب بهتر به شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>آیا اعتماد به نفس ارثی است؟</h3><p>خلق‌وخو تا حدی ارثی است، اما اعتماد به نفس بیشتر از تجربه‌ها، رابطه‌ها و شیوه‌ی گفتگو با خود شکل می‌گیرد و قابل تغییر است.</p><h3>فرق اعتماد به نفس و غرور چیست؟</h3><p>اعتماد به نفس یعنی باور به توانایی خود بدون نیاز به کوچک کردن دیگران. غرور و خودبزرگ‌بینی معمولاً پوششی برای ناامنی است.</p><h3>چقدر طول می‌کشد اعتماد به نفس بالا برود؟</h3><p>با تمرین منظم، بیشتر افراد در چند هفته تغییرهای کوچک و در چند ماه تغییرهای محسوس می‌بینند.</p><h2>جمع‌بندی</h2><p>اعتماد به نفس با کارهای کوچک و تکراری ساخته می‌شود: انجام دادن کاری که از آن می‌ترسیم، دیدن موفقیت‌ها، و مهربانی با خود در شکست‌ها. لازم نیست صبر کنید تا «حس» اعتماد به نفس بیاید؛ اول عمل کنید، حس پشت سرش می‌آید.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/10/%D8%B9%D8%B2%D8%AA-%D9%86%D9%81%D8%B3-%D8%B1%D9%88%D8%B2%D9%86%D8%A8%D8%B1%DA%AF" target="_blank" rel="noopener">عزت نفس روزنبرگ</a> | <a href="https://www.betterchoice.ir/fa/qdetail/14/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%B4%D9%81%D9%82%D8%AA-%D8%A8%D9%87-%D8%AE%D9%88%D8%AF" target="_blank" rel="noopener">مقیاس شفقت به خود</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/912/%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3-%D8%A7%D8%B1%D8%B2%D9%85%D9%86%D8%AF%DB%8C" target="_blank" rel="noopener">احساس ارزشمندی</a> | <a href="https://www.betterchoice.ir/fa/edu/561/%D8%B4%D9%81%D9%82%D8%AA-%D9%88%D8%B1%D8%B2%DB%8C-%D8%A8%D9%87-%D8%AE%D9%88%D8%AF" target="_blank" rel="noopener">شفقت‌ورزی به خود</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6692/%DA%86%D8%B7%D9%88%D8%B1_%D8%A7%D8%B9%D8%AA%D9%85%D8%A7%D8%AF_%D8%A8%D9%87_%D9%86%D9%81%D8%B3_%D8%A8%DB%8C%D8%B4%D8%AA%D8%B1%DB%8C_%D8%AF%D8%A7%D8%B4%D8%AA%D9%87_%D8%A8%D8%A7%D8%B4%DB%8C%D9%85" target="_blank" rel="noopener">چطور اعتماد به نفس بیشتری داشته باشیم؟</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6711/%D8%B9%D8%B2%D8%AA_%D9%86%D9%81%D8%B3_%DA%86%DB%8C%D8%B3%D8%AA" target="_blank" rel="noopener">عزت نفس چیست؟</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6687/%D8%A7%DA%AF%D8%B1_%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3_%D8%A8%DB%8C%E2%80%8C%D8%A7%D8%B1%D8%B2%D8%B4%DB%8C_%D9%85%DB%8C%E2%80%8C%DA%A9%D9%86%DB%8C%D8%AF_%D8%A7%DB%8C%D9%86_%DB%B5_%DA%A9%D8%A7%D8%B1_%D8%B1%D8%A7_%D8%A7%D9%86%D8%AC%D8%A7%D9%85_%D8%AF%D9%87%DB%8C%D8%AF" target="_blank" rel="noopener">اگر احساس بی‌ارزشی می‌کنید، این ۵ کار را انجام دهید</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6673/%D9%81%D8%B1%D9%85%D9%88%D9%84_%D8%A7%D8%B3%D8%B1%D8%A7%D8%B1%D8%A2%D9%85%DB%8C%D8%B2_%D8%AE%D9%88%D8%AF%D8%B4%D9%81%D9%82%D8%AA%E2%80%8C%D9%88%D8%B1%D8%B2%DB%8C" target="_blank" rel="noopener">فرمول اسرارآمیز خودشفقت‌ورزی</a></p></div>','["Psych Central. 5 ways to build your self-esteem. https://psychcentral.com/health/12-simple-activities-you-can-do-to-start-building-self-esteem-today", "Psych Central. Benefits of self-compassion: 7 benefits and how to practice. https://psychcentral.com/blog/practicing-self-compassion-when-you-have-a-mental-illness", "Psychology Today. 6 science-based self-compassion exercises. https://www.psychologytoday.com/us/blog/click-here-for-happiness/202101/6-science-based-self-compassion-exercises", "Breines, J. G., &amp; Chen, S. (2012). Self-compassion increases self-improvement motivation. Personality and Social Psychology Bulletin, 38(9), 1133–1143. https://www.semanticscholar.org/paper/Self-Compassion-Increases-Self-Improvement-Breines-Chen/d80137e87e00ecfe0882d8a8dbeecdf696df59de"]'::jsonb,false,true),
('a3','رابطه‌ی عاطفی سالم چه ویژگی‌هایی دارد؟','با دوستتان در کافه نشسته‌اید و او از رابطه‌اش تعریف می‌کند. همه‌چیز عالی به نظر می‌رسد، اما شما ته دلتان مطمئن نیستید رابطه‌ی خودتان «عادی» است یا نه. دعوا می‌کنید، گاهی دلخور می‌شوید، و گاهی فکر می‌کنید «آیا این همان چیزی است که باید باشد؟» پرسش از رابطه‌ی سالم از مهم‌ترین پرسش‌هایی است که می‌شود درباره‌ی زندگی عاطفی پرسید.','relations',8,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۳','img/articles/a3-cover.jpg','img/articles/a3-thumb.jpg','<p>در این مقاله می‌بینیم رابطه‌ی سالم دقیقاً چیست، چه ویژگی‌هایی دارد، و چطور می‌شود رابطه را به سمت سلامت بیشتر برد.</p><h2>قصه‌ی مهسا و رضا: هم‌خانه یا همسر؟</h2><p>مهسا بیست‌ونه سال دارد و کارشناس منابع انسانی است؛ رضا سی‌ودو سال دارد و برنامه‌نویس. دو سال پیش، بعد از سه سال آشنایی، ازدواج کردند. دوران نامزدی‌شان پر از شور بود: پیام‌های طولانی شبانه، قرارهای کافه، و ساعت‌ها حرف زدن درباره‌ی آینده. مهسا همیشه به دوستانش می‌گفت: «رضا بهترین دوست من است.»</p><p>اما حالا، دو سال بعد، چیزی کم شده بود. هر دو تمام‌وقت کار می‌کردند. شب‌ها، بعد از شام، رضا با لپ‌تاپش روی مبل می‌نشست و مهسا با گوشی‌اش روی تخت. گاهی کل شب جز «شام چی بخوریم؟» و «قبض برق را پرداختی؟» حرفی بینشان رد و بدل نمی‌شد. دعوا نمی‌کردند؛ مشکل همین بود. فقط کنار هم، اما جدا از هم، زندگی می‌کردند.</p><p>یک شب مهسا خواست از اتفاقی در محل کار تعریف کند. همکارش جلوی جمع او را تحقیر کرده بود و حالش خیلی بد بود. گفت: «رضا، امروز یک اتفاق بد افتاد...» رضا، بدون اینکه چشم از صفحه‌ی لپ‌تاپ بردارد، گفت: «اوهوم، چی شد؟» مهسا چند جمله گفت و دید رضا همچنان دارد تایپ می‌کند. ساکت شد. رضا متوجه نشد. چند دقیقه بعد پرسید: «خب، بعدش؟» و مهسا گفت: «هیچی، مهم نیست.» و به اتاق رفت.</p><p>آن شب مهسا در تاریکی اتاق فکر کرد: «آیا این همان رابطه‌ای است که می‌خواستم؟ آیا ما هنوز عاشق هم هستیم؟» چند روز بعد، وقتی خواهرش از رابطه‌اش پرسید، مهسا برای اولین بار گفت: «نمی‌دانم. حس می‌کنم فقط هم‌خانه‌ایم.» خواهرش پرسید: «به خودش گفته‌ای؟» و مهسا فهمید که نگفته. می‌ترسید اگر بگوید، دعوا شود؛ یا بدتر، رضا بگوید که او هم همین حس را دارد.</p><p>یک جمعه صبح، رضا برای مهسا صبحانه درست کرد؛ کاری که ماه‌ها نکرده بود. مهسا تعجب کرد. رضا گفت: «دیشب دیدم توی خواب گریه می‌کردی. فکر کنم یک جای کارمان می‌لنگد.» مهسا بغض کرد و همه‌چیز را گفت. رضا گوش داد، این بار بدون گوشی، بدون لپ‌تاپ. در آخر گفت: «من هم دلم برای خودمان تنگ شده. بیا کمک بگیریم.»</p><h2>رابطه‌ی من چقدر سالم است؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند تجربه‌ی خودتان را روشن‌تر ببینید. اگر به چند مورد پاسخ «بله» دادید، صحبت با یک متخصص می‌تواند مفید باشد.</p><ol><li>آیا می‌توانید ناراحتی‌ها و نیازهایتان را بدون ترس از تمسخر یا واکنش تند بگویید؟</li><li>آیا حتی در دعوا، به هم توهین یا همدیگر را تحقیر نمی‌کنید؟</li><li>آیا هرکدام دوستان و علایق خودتان را دارید و این برای دیگری مشکلی نیست؟</li><li>آیا وقتی «نه» می‌گویید، به آن احترام گذاشته می‌شود؟</li><li>آیا وقتی همسرتان توجه می‌خواهد، معمولاً به سمتش برمی‌گردید و گوش می‌دهید؟</li><li>آیا بعد از دعوا راهی برای آشتی و ترمیم پیدا می‌کنید؟</li><li>آیا بیشتر وقت‌ها کنار او احساس آرامش می‌کنید؟</li></ol><h2>رابطه‌ی سالم چیست؟</h2><p>رابطه‌ی سالم رابطه‌ی بی‌دعوا یا بی‌نقص نیست. رابطه‌ای است که در آن هر دو نفر بیشتر وقت‌ها احساس امنیت، احترام و آزادی برای خود بودن دارند. در چنین رابطه‌ای اختلاف هست، اما به تحقیر و ترس ختم نمی‌شود.</p><p>پژوهش‌های مؤسسه‌ی گاتمن نشان می‌دهد یکی از قوی‌ترین پیش‌بینی‌کننده‌های موفقیت رابطه، کارهای کوچک روزمره است: اینکه وقتی یکی از دو نفر «درخواست توجه» می‌کند، مثلاً می‌گوید «ببین چه پرنده‌ی قشنگی!»، دیگری به سمتش رو کند یا نه. زوج‌های شاد در گفتگوهای روزمره به‌مراتب بیشتر از زوج‌های پرتنش به هم رو می‌کنند.</p><p>یعنی سلامت رابطه بیشتر در لحظه‌های معمولی ساخته می‌شود تا در لحظه‌های بزرگ.</p><h2>۸ ویژگی رابطه‌ی عاطفی سالم</h2><ol><li>احترام: حتی در عصبانیت، تحقیر، تمسخر و توهین جایی ندارد.</li><li>اعتماد: لازم نیست مدام گوشی هم را چک کنید یا نگران پنهان‌کاری باشید.</li><li>گفتگوی باز: می‌توانید نیازها، ناراحتی‌ها و ترس‌هایتان را بدون ترس از تمسخر یا تنبیه بگویید.</li><li>فردیت: هرکدام دوستان، علایق و فضای شخصی خود را دارید. رابطه شما را کوچک نمی‌کند؛ بزرگ‌تر می‌کند.</li><li>مرزهای روشن: «نه» گفتن ممکن است و به آن احترام گذاشته می‌شود.</li><li>حل تعارض: دعواها به نتیجه یا دست‌کم به فهم بیشتر می‌رسند، نه اینکه بی‌پایان تکرار شوند.</li><li>حمایت: در موفقیت‌ها خوشحالی و در سختی‌ها همراهی هست.</li><li>توازن قدرت: تصمیم‌ها مشترک‌اند و یک نفر همیشه حرف آخر را نمی‌زند.</li></ol><p>در مقابل، نشانه‌های رابطه‌ی ناسالم: کنترل، انتقاد مداوم، انزوا از دوستان و خانواده، ترس از واکنش طرف مقابل، و حس اینکه باید خودتان را کوچک کنید.</p><h2>چطور رابطه را سالم‌تر کنیم؟</h2><ol><li>به درخواست‌های کوچک پاسخ دهید. سر بلند کردن از گوشی، پرسیدن «روزت چطور بود؟» و گوش دادن واقعی، آجرهای اعتمادند.</li><li>نیاز را بگویید، نه شکایت را. «دلم برایت تنگ شده، امشب با هم شام بخوریم؟» به‌جای «تو دیگر هیچ وقتی برای من نداری».</li><li>با هم قرارهای کوچک داشته باشید. آیین‌های ساده، مثل قهوه‌ی صبح یا پیاده‌روی آخر هفته، پیوند را زنده نگه می‌دارند.</li><li>مرزهایتان را بشناسید و بگویید. چه چیزی برایتان قابل قبول نیست؟ گفتن آرام و روشن آن، به رابطه آسیب نمی‌زند؛ از آن محافظت می‌کند.</li><li>بعد از دعوا ترمیم کنید. عذرخواهی واقعی، پذیرش سهم خود، و برگشتن به گفتگو، از دعوا یک فرصت می‌سازد.</li><li>قدردانی را عادت کنید. دیدن و گفتن خوبی‌های کوچک، تعادل را به سمت مثبت می‌برد.</li></ol><p>برگردیم به مهسا و رضا. در مشاوره قرار گذاشتند هر شب بیست دقیقه بدون گوشی درباره‌ی روزشان حرف بزنند. اوایل زورکی بود. یک ماه بعد، مهسا گفت «انگار دوباره دوستش دارم، نه فقط کنارش زندگی می‌کنم».</p><p>البته مسیر همیشه صاف نبود. هفته‌ی دوم، رضا وسط یکی از همین گفتگوها گوشی‌اش را برداشت تا پیامی کاری را جواب دهد و مهسا دلخور شد. قبلاً چنین لحظه‌ای به قهری چندروزه ختم می‌شد. این بار مهسا گفت: «وقتی وسط حرفم گوشی را برمی‌داری، حس می‌کنم مهم نیستم.» رضا اول خواست از خودش دفاع کند، اما مکث کرد و گفت: «حق داری. پیام را بعداً جواب می‌دهم.» همین گفتگوی کوتاه، که شاید از بیرون بی‌اهمیت به نظر برسد، دقیقاً همان چیزی است که رابطه‌ی سالم را می‌سازد: گفتن نیاز بدون حمله، و شنیدن آن بدون دفاع.</p><p>چند ماه بعد، آن‌ها قانون دیگری هم اضافه کردند: آخر هر هفته، هرکدام یک چیز را که از دیگری ممنون است بگوید. مهسا می‌گفت این جمله‌های کوچک، مثل «ممنون که وقتی خسته بودم شام را درست کردی»، بیشتر از هر هدیه‌ای به او حس دیده شدن می‌دهد. رضا هم فهمید که مهسا برای دوست داشته شدن، به کارهای بزرگ نیاز ندارد؛ به توجه پیوسته نیاز دارد.</p><p>یک تمرین برای همین هفته: امشب از همسر یا شریک زندگی‌تان بپرسید: «این هفته چه کاری از من باعث شد احساس کنی دوستت دارم؟» و بعد فقط گوش دهید، بدون توضیح یا دفاع. جواب‌ها معمولاً ساده‌تر از آن‌اند که فکر می‌کنیم: یک چای، یک پیام کوتاه وسط روز، یا گوش دادن بدون گوشی. همین جواب‌ها نقشه‌ی دقیقی از زبان محبت او به شما می‌دهند.</p><h2>باورهای نادرست رایج درباره‌ی رابطه‌ی سالم</h2><p>«اگر واقعاً عاشق باشیم، هیچ‌وقت دعوا نمی‌کنیم.» دو آدم متفاوت، دیر یا زود اختلاف نظر پیدا می‌کنند. رابطه‌ای که در آن هیچ اختلافی بروز نمی‌کند، گاهی رابطه‌ای است که در آن یک نفر حرفش را نمی‌زند.</p><p>«همسرم باید بدون گفتن بفهمد چه می‌خواهم.» ذهن‌خوانی انتظار ناعادلانه‌ای است. گفتن روشن نیازها نشانه‌ی ضعف رابطه نیست، نشانه‌ی بلوغ آن است.</p><p>«حسادت نشانه‌ی عشق است.» کمی حس نگرانی طبیعی است، اما حسادتی که به کنترل، بازجویی و محدود کردن ختم شود، نشانه‌ی ناامنی است، نه عشق.</p><p>«در رابطه‌ی خوب همه‌ی کارها را با هم انجام می‌دهیم.» نزدیکی سالم با حفظ فردیت ممکن است. زوج‌هایی که دوستان و علایق جداگانه هم دارند، معمولاً انرژی بیشتری برای رابطه‌ی مشترکشان دارند.</p><p>«رابطه‌ی خوب خودش پیش می‌رود.» رابطه مثل باغچه است: بدون رسیدگی، حتی اگر خاکش خوب باشد، علف هرز می‌گیرد. توجه روزمره و کارهای کوچک، آن را زنده نگه می‌دارد.</p><p>«اگر سختی داریم، حتماً اشتباه انتخاب کرده‌ایم.» همه‌ی رابطه‌ها دوره‌های سخت دارند، مثل تولد فرزند، فشار مالی یا بیماری. سختی به‌تنهایی نشانه‌ی انتخاب اشتباه نیست؛ شیوه‌ی عبور از آن مهم است.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر حس می‌کنید در رابطه گم شده‌اید، دعواها تکراری و فرساینده شده‌اند، یا نمی‌دانید رابطه‌تان سالم است یا آسیب‌زا، مشاوره‌ی فردی یا زوج کمک می‌کند تصویر روشن‌تری داشته باشید. برای مشاوره، با مرکز مشاوره‌ی انتخاب بهتر به شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>آیا در رابطه‌ی سالم دعوا نمی‌شود؟</h3><p>می‌شود. تفاوت در شیوه‌ی دعوا و ترمیم بعد از آن است.</p><h3>از کجا بفهمم رابطه‌ام سمی است یا فقط مشکل دارد؟</h3><p>اگر ترس، کنترل، تحقیر یا انزوا الگوی ثابت رابطه است، احتمالاً با رابطه‌ی آسیب‌زا روبه‌رو هستید. اگر مشکل در مهارت‌های گفتگوست، معمولاً قابل حل است.</p><h3>آیا رابطه‌ی ناسالم را می‌شود سالم کرد؟</h3><p>اگر هر دو نفر بخواهند و خشونت در کار نباشد، بسیاری از الگوها قابل تغییرند.</p><h2>جمع‌بندی</h2><p>رابطه‌ی سالم جایی است که هر دو نفر می‌توانند خودشان باشند و در عین حال احساس نزدیکی کنند. این رابطه با کارهای کوچک و تکراری ساخته می‌شود: توجه، احترام، گفتگو و ترمیم.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/2/%D8%B5%D9%85%DB%8C%D9%85%DB%8C%D8%AA-%D9%88%D8%A7%DA%A9%D8%B1-%D9%88-%D8%AA%D8%A7%D9%85%D9%BE%D8%B3%D9%88%D9%86" target="_blank" rel="noopener">صمیمیت واکر و تامپسون</a> | <a href="https://www.betterchoice.ir/fa/qdetail/25/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3-%D9%85%D8%AB%D8%A8%D8%AA-%D8%A8%D9%87-%D9%87%D9%85%D8%B3%D8%B1" target="_blank" rel="noopener">پرسشنامه احساس مثبت به همسر</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/350/%D8%BA%D9%86%DB%8C-%D8%B3%D8%A7%D8%B2%DB%8C-%D8%B1%D9%88%D8%A7%D8%A8%D8%B7" target="_blank" rel="noopener">غنی سازی روابط</a> | <a href="https://www.betterchoice.ir/fa/edu/809/%D9%85%D8%B9%D8%AC%D9%88%D9%86-%D8%B1%D8%A7%D8%A8%D8%B7%D9%87-%D9%87%D8%A7" target="_blank" rel="noopener">معجون رابطه ها</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/print/news/6592" target="_blank" rel="noopener">رابطه موفق</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6689/%DB%B8_%D8%B1%D9%88%D8%B4_%D8%A8%D8%B1%D8%A7%DB%8C_%D8%A7%DB%8C%D9%86%DA%A9%D9%87_%D8%B1%D8%A7%D8%A8%D8%B7%D9%87_%D8%B9%D8%A7%D8%B4%D9%82%D8%A7%D9%86%D9%87%E2%80%8C%D8%AA%D8%B1%DB%8C_%D8%AF%D8%A7%D8%B4%D8%AA%D9%87_%D8%A8%D8%A7%D8%B4%DB%8C%D8%AF" target="_blank" rel="noopener">۸ روش برای اینکه رابطه عاشقانه‌تری داشته باشید</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6791" target="_blank" rel="noopener">چطور خودتان را برای یک رابطه سالم آماده کنید: ۱۲ گام اساسی (قسمت اول)</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6795" target="_blank" rel="noopener">آیا او همان فرد مناسب است؟ ۱۰ نشانه که با فرد درست رابطه دارید (قسمت اول)</a></p></div>','["The Gottman Institute. The sound relationship house: Turn towards instead of away. https://www.gottman.com/blog/the-sound-relationship-house-turn-towards-instead-of-away/", "The Gottman Institute. An introduction to emotional bids and trust. https://www.gottman.com/blog/an-introduction-to-emotional-bids-and-trust/", "Psych Central. Toxic relationships: 8 signs. https://psychcentral.com/relationships/signs-of-toxic-relationships", "Psychology Today. 51 signs of an unhealthy relationship. https://www.psychologytoday.com/us/blog/in-practice/201502/51-signs-of-an-unhealthy-relationship"]'::jsonb,true,true),
('a4','سوگ: چطور با مرگ عزیز کنار بیاییم؟','از دست دادن کسی که دوستش داریم، زندگی را به «قبل» و «بعد» تقسیم می‌کند. غم، دلتنگی، خشم، احساس گناه و حتی بی‌حسی، همه بخشی از واکنش طبیعی ما به این فقدان‌اند. کنار آمدن با سوگ یعنی یاد گرفتن زندگی با جای خالی کسی که دیگر نیست؛ مسیری که برای هر کس شکل خودش را دارد. در این مقاله، اول قصه‌ی یک نفر را می‌خوانیم، بعد چند پرسش برای شناختن حال خودمان مطرح می‌کنیم، و سپس می‌بینیم سوگ چگونه کار می‌کند و چه چیزی واقعاً کمک می‌کند.','mental',6,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۴','img/articles/a4-cover.jpg','img/articles/a4-thumb.jpg','<h2>قصه‌ی فاطمه: صندلی خالی سر سفره</h2><p>فاطمه پنجاه‌وپنج سال دارد. سی‌ویک سال با حسین زندگی کرد؛ مردی آرام که هر صبح قبل از رفتن به سر کار، برای فاطمه چای دم می‌کرد. یک روز اسفند، حسین سر کار دچار سکته‌ی قلبی شد و تا آمبولانس برسد، تمام کرده بود. فاطمه حتی فرصت خداحافظی نداشت. آخرین جمله‌ای که به او گفته بود، گله‌ای کوچک درباره‌ی نان بود که یادش رفته بود بخرد.</p><p>روزهای اول، خانه پر از مهمان بود و فاطمه انگار در خواب راه می‌رفت. گریه نمی‌کرد؛ فقط مات بود. بعد از چهلم، خانه خلوت شد و غم مثل موج آمد. صبح‌ها بی‌اختیار دو استکان چای می‌ریخت و تازه یادش می‌آمد. شب‌ها لباس‌های حسین را بو می‌کرد. گاهی وسط آشپزی صدای کلید را در قفل می‌شنید و دلش فرو می‌ریخت.</p><p>از همه سخت‌تر، آن جمله‌ی آخر بود. فاطمه بارها در ذهنش آن صبح را مرور می‌کرد: «اگر به‌جای غر زدن، فقط گفته بودم مراقب خودت باش...» این فکر او را رها نمی‌کرد. گاهی هم از حسین عصبانی می‌شد که چرا به حرفش گوش نکرده بود و چکاپ قلبش را عقب انداخته بود؛ و بعد از این عصبانیت، احساس گناه بیشتری می‌کرد.</p><p>دخترش، مریم، سعی می‌کرد او را بیرون ببرد، اما فاطمه حوصله‌ی هیچ‌جا را نداشت. اتاق کار حسین را دست‌نخورده نگه داشته بود و هر روز ساعت‌ها آنجا می‌نشست. چند ماه بعد، دوستی به او گفت: «دیگر وقتش است که فراموشش کنی.» فاطمه آن شب تا صبح گریه کرد. نمی‌خواست فراموش کند. فقط می‌خواست این‌قدر درد نکشد.</p><p>کم‌کم زندگی روزمره هم از دستش در رفت. قبض‌ها پرداخت نشده می‌ماند، چون همیشه حسین پرداختشان می‌کرد. گلدان‌های بالکن، که هر دو با هم آبشان می‌دادند، یکی‌یکی خشک شدند. به مهمانی‌های خانوادگی نمی‌رفت، چون دیدن زوج‌های دیگر کنار هم برایش طاقت‌فرسا بود. وقتی دوستانش زنگ می‌زدند، می‌گفت «خوبم» و زود قطع می‌کرد.</p><p>یک سال گذشت و فاطمه همچنان بیشتر روزها را در آن اتاق می‌گذراند. مریم نگران شد و با اصرار او را پیش مشاور برد. اولین چیزی که فاطمه در جلسه گفت این بود: «نمی‌دانم دارم درست سوگواری می‌کنم یا نه. انگار گیر کرده‌ام.»</p><h2>حال من چطور است؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها برای تشخیص نیستند. فقط کمک می‌کنند ببینید سوگتان در مسیر طبیعی است یا شاید به حمایت بیشتری نیاز دارید. اگر مدت زیادی از فقدان گذشته و به بیشتر این پرسش‌ها پاسخ «بله» می‌دهید، صحبت با یک متخصص می‌تواند کمک کند.</p><ol><li>آیا بیش از یک سال از فقدان گذشته و هنوز تقریباً هر روز دلتنگی شدید و دردناکی دارید؟</li><li>آیا هنوز پذیرفتن مرگ او برایتان بسیار سخت است، طوری که گاهی باور نمی‌کنید واقعاً رفته؟</li><li>آیا ذهنتان بیشتر وقت‌ها درگیر او یا شرایط مرگش است؟</li><li>آیا حس می‌کنید بخشی از خودتان یا هویتتان همراه او از بین رفته؟</li><li>آیا از هر چیزی که یادآور مرگ اوست به‌شدت دوری می‌کنید؟</li><li>آیا حس می‌کنید زندگی بدون او معنایی ندارد؟</li><li>آیا برگشتن به کار، رابطه‌ها یا برنامه‌ی روزانه برایتان بسیار سخت شده است؟</li></ol><h2>سوگ چیست و چرا این‌قدر بالا و پایین دارد؟</h2><p>سوگ واکنش طبیعی ما به از دست دادن کسی است که به او دلبسته بودیم. احتمالاً درباره‌ی «پنج مرحله‌ی سوگ» شنیده‌اید: انکار، خشم، چانه‌زنی، افسردگی و پذیرش. این الگو مشهور است، اما سوگ معمولاً پله‌پله و به ترتیب پیش نمی‌رود.</p><p>یکی از الگوهای پژوهشی مهم، مدل دوفرایندی است که استروبه و شوت مطرح کرده‌اند. طبق این مدل، آدم سوگوار بین دو حالت در رفت‌وآمد است:</p><ul><li>رو به فقدان: گریه، دلتنگی، مرور خاطره‌ها</li><li>رو به بازسازی: رسیدگی به کارهای روزمره، نقش‌های تازه، و استراحت از غم</li></ul><p>این رفت‌وآمد انعطاف‌پذیر سالم است. روزی که کمی خندیدید، خیانت به عزیزتان نیست؛ بخشی از مسیر است. فاطمه، با ماندن همیشگی در اتاق حسین، فقط در یک سمت این رفت‌وآمد گیر کرده بود.</p><p>برای بیشتر آدم‌ها، شدت سوگ به‌تدریج کم می‌شود. اما فراتحلیلی روی چهارده مطالعه نشان داد حدود ۱۰ درصد سوگواران بزرگسال دچار سوگ طولانی می‌شوند؛ حالتی که در آن درد شدید و دلمشغولی با متوفی برای مدت طولانی ادامه پیدا می‌کند و زندگی را مختل می‌کند.</p><h2>واکنش‌های رایج در سوگ</h2><ul><li>غم و دلتنگی که موج‌وار می‌آید و می‌رود</li><li>ناباوری و بی‌حسی، به‌خصوص در هفته‌های اول</li><li>خشم به خود، به دیگران، یا حتی به عزیز ازدست‌رفته</li><li>احساس گناه: «اگر زودتر فهمیده بودم...»</li><li>مشکلات خواب و اشتها</li><li>ضعف تمرکز و فراموشی</li><li>علائم جسمی: خستگی، سنگینی سینه، سردرد</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>به غم اجازه دهید. سوگ سرکوب‌شده از بین نمی‌رود. گریه، حرف زدن و نوشتن، راه‌های سالم بیرون آمدن آن‌اند.</li><li>از غم هم استراحت کنید. کمک گرفتن برای کارهای روزمره، دیدن دوستان، یا حتی تماشای یک فیلم، بخشی از کنار آمدن است، نه فرار از آن.</li><li>پیوند را به شکلی تازه نگه دارید. نامه نوشتن به او، نگه داشتن یک یادگاری، یا ادامه دادن کاری که دوست داشت، کمک می‌کند ارتباط درونی‌تان شکل تازه‌ای پیدا کند.</li><li>با احساس گناه مهربان باشید. حرف‌های ناگفته و جمله‌های آخر، ذهن سوگوار را رها نمی‌کنند. یادتان باشد رابطه‌ی شما با سال‌ها لحظه ساخته شده، نه با یک جمله.</li><li>مراقب بدنتان باشید. سوگ خسته‌کننده است. خواب، غذا و کمی تحرک، پایه‌ی تحمل روزهای سخت‌اند.</li><li>سالگردها را از قبل برنامه‌ریزی کنید. این روزها معمولاً سخت‌ترند. از قبل فکر کنید چطور و با چه کسی بگذرانیدشان.</li></ol><p>فاطمه در مشاوره، به‌جای «فراموش کردن»، دفترچه‌ای شروع کرد از چیزهایی که از حسین یاد گرفته بود. نامه‌ای هم به او نوشت و همان جمله‌ای را که آن صبح نگفته بود، رویش نوشت. کم‌کم اتاق را مرتب کرد و میز حسین را گوشه‌ی نشیمن گذاشت. گفت: «حالا حس می‌کنم با من زندگی می‌کند، نه اینکه من در گذشته زندگی کنم.»</p><h2>باورهای نادرست رایج درباره‌ی سوگ</h2><p>«باید قوی باشی و گریه نکنی.» گریه ضعف نیست؛ یکی از راه‌های طبیعی بیرون آمدن درد است.</p><p>«بعد از یک سال باید تمام شده باشد.» سوگ تقویم ثابتی ندارد. موج‌های غم ممکن است سال‌ها بعد، در مناسبت‌ها، برگردند.</p><p>«حرف زدن درباره‌ی او حال را بدتر می‌کند.» برای بسیاری از سوگواران، حرف زدن درباره‌ی عزیز ازدست‌رفته آرامش‌بخش است.</p><p>«خندیدن در دوره‌ی سوگ بی‌احترامی است.» لحظه‌های شادی بخشی طبیعی از رفت‌وآمد بین غم و زندگی‌اند.</p><p>«باید او را فراموش کنی تا آرام شوی.» بسیاری از سوگواران با حفظ نوعی پیوند درونی با عزیزشان بهتر کنار می‌آیند.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر ماه‌ها گذشته و غم همچنان همه‌ی زندگی را گرفته، اگر نمی‌توانید کارهای روزمره را انجام دهید، اگر مرگ ناگهانی یا خشونت‌آمیز بوده، یا اگر احساس می‌کنید زندگی بدون او معنایی ندارد، با یک متخصص صحبت کنید. درمان‌های ویژه‌ی سوگ طولانی اثربخشی خوبی نشان داده‌اند. برای مشاوره، با مرکز مشاوره‌ی انتخاب بهتر به شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>سوگ چقدر طول می‌کشد؟</h3><p>زمان ثابتی ندارد. شدت آن برای بیشتر افراد به‌تدریج کم می‌شود، اما موج‌های غم ممکن است سال‌ها، به‌خصوص در مناسبت‌ها، برگردند.</p><h3>آیا باید مراحل سوگ را به ترتیب طی کنم؟</h3><p>نه. مراحل سوگ نقشه‌ی ثابتی نیستند. رفت‌وآمد بین غم و زندگی روزمره طبیعی است.</p><h3>چطور به کسی که سوگوار است کمک کنم؟</h3><p>حضور داشته باشید، گوش دهید، و کمک عملی بدهید. لازم نیست جمله‌ی کاملی پیدا کنید؛ «من اینجا هستم» کافی است.</p><h2>جمع‌بندی</h2><p>سوگ بهایی است که برای دوست داشتن می‌پردازیم. کنار آمدن با سوگ به معنای فراموش کردن نیست؛ یعنی یاد بگیریم با فقدان زندگی کنیم و پیوندمان با او را به شکلی تازه نگه داریم. لازم نیست این راه را تنها بروید.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/16/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%A7%D9%81%D8%B3%D8%B1%D8%AF%DA%AF%DB%8C--%D8%A7%D8%B6%D8%B7%D8%B1%D8%A7%D8%A8--%D8%A7%D8%B3%D8%AA%D8%B1%D8%B3" target="_blank" rel="noopener">مقیاس افسردگی، اضطراب، استرس (DASS)</a> | <a href="https://www.betterchoice.ir/fa/qdetail/27/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3-%D8%AA%D9%86%D9%87%D8%A7%DB%8C%DB%8C--UCLA-" target="_blank" rel="noopener">مقیاس احساس تنهایی (UCLA)</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/563/%D8%B3%D9%88%DA%AF-%D9%88-%D8%AF%D8%A7%D8%BA%D8%AF%DB%8C%D8%AF%DA%AF%DB%8C" target="_blank" rel="noopener">سوگ و داغدیدگی</a> | <a href="https://www.betterchoice.ir/fa/edu/706/%DA%86%DA%AF%D9%88%D9%86%D9%87-%D8%A7%D8%B2-%D8%B3%D9%86%DA%AF-%D8%AD%D9%88%D8%A7%D8%AF%D8%AB-%D9%85%DB%8C-%D8%AA%D9%88%D8%A7%D9%86-%D8%AE%D8%A7%D9%86%D9%87-%D8%B3%D8%A7%D8%AE%D8%AA-" target="_blank" rel="noopener">چگونه از سنگ حوادث می‌توان خانه ساخت؟</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6800/%DA%A9%D9%86%D8%A7%D8%B1_%D8%A2%D9%85%D8%AF%D9%86_%D8%A8%D8%A7_%D8%B3%D9%88%DA%AF_%D8%B3%D9%88%DA%AF%D9%88%D8%A7%D8%B1%DB%8C_%DA%AF%D8%B3%D8%AA%D8%B1%D8%B4_%D9%88_%D8%AA%DA%A9%D8%A7%D9%85%D9%84" target="_blank" rel="noopener">کنار آمدن با سوگ: سوگواری، گسترش و تکامل</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6770/%DB%B6_%D9%85%D9%87%D8%A7%D8%B1%D8%AA_%D8%A7%D9%86%D8%B7%D8%A8%D8%A7%D9%82%DB%8C_%D8%AF%D8%B1_%D8%B2%D9%85%D8%A7%D9%86_%D8%B3%D9%88%DA%AF" target="_blank" rel="noopener">۶ مهارت انطباقی در زمان سوگ</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6666/%D9%86%D9%88%D8%B9_%D8%AA%D8%A7%D8%B2%D9%87%E2%80%8C%D8%A7%DB%8C_%D8%A7%D8%B2_%D8%AA%D9%86%D9%87%D8%A7%DB%8C%DB%8C_%D8%AF%D8%B1%DA%A9_%D9%88_%D8%AA%D8%AD%D9%84%DB%8C%D9%84_%D8%A7%D8%B2_%D8%AF%D8%B3%D8%AA_%D8%AF%D8%A7%D8%AF%D9%86_%D8%B1%D9%88%D8%A7%D8%A8%D8%B7_%D9%85%D8%B9%D9%86%D8%A7%D8%AF%D8%A7%D8%B1" target="_blank" rel="noopener">نوع تازه‌ای از تنهایی (درک و تحلیل از دست دادن روابط معنادار)</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6532/%D9%81%D8%B1%D9%85%D9%88%D9%84_%D8%AA%D8%A7%D8%A8%E2%80%8C%D8%A2%D9%88%D8%B1%DB%8C" target="_blank" rel="noopener">فرمول تاب‌آوری</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6573" target="_blank" rel="noopener">درک سوگ و چگونگی پاسخ به آن</a></p></div>','["Stroebe, M., &amp; Schut, H. (1999). The dual process model of coping with bereavement: Rationale and description. Death Studies, 23(3), 197–224. https://www.semanticscholar.org/paper/The-dual-process-model-of-coping-with-bereavement:-Stroebe-Schut/cf85f8697463875964ccd34636f742f860505411", "Lundorff, M., Holmgren, H., Zachariae, R., Farver-Vestergaard, I., &amp; O''Connor, M. (2017). Prevalence of prolonged grief disorder in adult bereavement: A systematic review and meta-analysis. Journal of Affective Disorders, 212, 138–149. https://pure.au.dk/portal/en/publications/prevalence-of-prolonged-grief-disorder-in-adult-bereavement-a-sys/", "Psychology Today. The dual-process model of grief. https://www.psychologytoday.com/us/blog/widows-walk/202310/the-dual-process-model-of-grief", "Psychology Today. Prolonged grief disorder. https://www.psychologytoday.com/us/conditions/prolonged-grief-disorder"]'::jsonb,false,true),
('a5','کودک لجباز: چرا لجبازی می‌کند و چطور بدون تنبیه رفتار کنیم؟','«کفشت را بپوش.» «نه!» «دیر شد، بپوش.» «نمی‌خوام!» ده دقیقه بعد شما کلافه‌اید، کودک روی زمین نشسته، و هنوز کفشی پایش نیست. لجبازی کودک از آن مشکلاتی است که صبور‌ترین والدین را هم به مرز انفجار می‌رساند. و هرچه سخت‌تر می‌گیریم، لجبازی محکم‌تر می‌شود.','parenting',7,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۵','img/articles/a5-cover.jpg','img/articles/a5-thumb.jpg','<p>این مقاله کمکتان می‌کند بفهمید پشت این «نه»‌ها چه می‌گذرد و چطور می‌شود بدون داد زدن و تنبیه، همکاری کودک را جلب کرد.</p><h2>قصه‌ی سارا: هر شب، همان جنگ</h2><p>سارا چهار سال دارد؛ دختری پرانرژی با موهای فرفری و اراده‌ای که پدرش، بابک، به شوخی می‌گوید «از سنگ محکم‌تر است». بابک سی‌ونه سال دارد و مهندس عمران است. از وقتی همسرش برای یک دوره‌ی کاری شیفت شب گرفته، شب‌ها خواباندن سارا با اوست، و این کار به سخت‌ترین بخش روزش تبدیل شده است.</p><p>ساعت نه شب، بابک می‌گوید: «سارا جان، وقت خواب است.» جواب همیشه یکی است: «نه!» بعد مذاکره شروع می‌شود: یک کارتون دیگر، یک قصه‌ی دیگر، یک لیوان آب، یک بار دیگر دستشویی. بابک اول کوتاه می‌آید، چون خسته است و حوصله‌ی دعوا ندارد. اما وقتی ساعت به ده و نیم می‌رسد، صبرش تمام می‌شود، صدایش بالا می‌رود، و سارا گریه‌کنان به اتاقش می‌رود.</p><p>یک شب، وقتی بابک گفت «همین الان مسواک بزن»، سارا مسواک را از دستش گرفت و به گوشه‌ی حمام پرت کرد. بابک بی‌اختیار فریاد زد: «بس است! امشب از قصه خبری نیست!» سارا جیغ زد، پایش را به زمین کوبید و گفت: «تو بابای بدی هستی!» آن شب سارا ساعت یازده، با چشم‌های پف‌کرده، خوابش برد و بابک تا نیمه‌شب روی مبل نشسته بود و به سقف خیره مانده بود.</p><p>صبح‌ها هم وضع بهتر نبود. سارا سر انتخاب لباس، خوردن صبحانه و حتی بستن کمربند صندلی ماشین مقاومت می‌کرد، و بابک بیشتر روزها با اعصاب خراب به محل کار می‌رسید.</p><p>بابک فکر می‌کرد مشکل از سارا است: «این بچه حرف‌گوش‌کن نیست.» اما مادرش، که یک روز برای کمک آمده بود، چیز دیگری دید. گفت: «بابک، تو از لحظه‌ای که سارا را از مهد آوردی، فقط به او دستور دادی. کفشت را دربیاور، دستت را بشوی، غذایت را بخور، تلویزیون را خاموش کن. این بچه تمام روز هیچ اختیاری نداشته.»</p><p>بابک اول ناراحت شد. اما آن شب، وقتی دوباره همان جنگ تکرار شد، حرف مادرش در ذهنش چرخید. فردای آن روز، از یک مشاور کودک وقت گرفت و اولین جمله‌اش این بود: «فکر می‌کنم من و دخترم هر شب داریم با هم مسابقه می‌دهیم و هر دو می‌بازیم.»</p><h2>آیا لجبازی فرزندم از حد معمول گذشته است؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند تجربه‌ی خودتان را روشن‌تر ببینید. اگر به چند مورد پاسخ «بله» دادید، صحبت با یک متخصص می‌تواند مفید باشد.</p><ol><li>آیا فرزندتان تقریباً با هر درخواستی مخالفت می‌کند، نه فقط گاهی؟</li><li>آیا اغلب عصبانی یا زودرنج است؟</li><li>آیا به نظر می‌رسد عمداً دیگران را آزار می‌دهد؟</li><li>آیا این رفتارها در مهدکودک یا مدرسه هم دیده می‌شود؟</li><li>آیا این وضعیت بیش از شش ماه ادامه داشته است؟</li><li>آیا اغلب در نهایت کوتاه می‌آیید تا دعوا تمام شود؟</li></ol><h2>لجبازی کودک چیست و چرا پیش می‌آید؟</h2><p>لجبازی یعنی مقاومت مکرر کودک در برابر درخواست‌ها و قانون‌ها. اما بیشتر وقت‌ها لجبازی «بد بودن» نیست؛ تلاش کودک برای داشتن کنترل است. کودکی که تقریباً در هیچ چیز اختیار ندارد، نه در ساعت خواب، نه در غذا، نه در برنامه‌ی روز، با «نه» گفتن حس می‌کند صاحب اختیار است.</p><p>دلیل‌های رایج لجبازی:</p><ul><li>مرحله‌ی رشد: در دو تا چهارسالگی و دوباره در نوجوانی، استقلال‌طلبی اوج می‌گیرد.</li><li>خلق‌وخوی ذاتی: بعضی کودکان از تولد پرانرژی‌تر و مصمم‌ترند.</li><li>جنگ قدرت: هرچه والد سخت‌تر پافشاری کند، کودک هم بیشتر مقاومت می‌کند.</li><li>نیاز به توجه: اگر لجبازی بیشترین توجه را به همراه دارد، تکرار می‌شود.</li><li>خستگی، گرسنگی یا فشار عاطفی: مثل تولد خواهر یا برادر جدید.</li></ul><p>به تعبیر یکی از راهنماهای Psych Central، ماهیت رفتار مقابله‌ای این است که والد را خسته کند تا کوتاه بیاید. برای همین آرامش و ثبات والد مهم‌ترین ابزار است.</p><h2>نشانه‌های لجبازی: طبیعی یا نگران‌کننده؟</h2><p>لجبازی معمول:</p><ul><li>«نه» گفتن به بعضی درخواست‌ها، به‌خصوص وقتی خسته است</li><li>کش دادن کارها مثل مسواک یا خوابیدن</li><li>چانه زدن بر سر قانون‌ها</li></ul><p>لجبازی نیازمند توجه بیشتر:</p><ul><li>مخالفت تقریباً با هر درخواستی، بیشتر روزها</li><li>خشم و کینه‌ی مداوم، عمداً آزار دادن دیگران</li><li>مشکل مشابه در مهدکودک یا مدرسه</li><li>ادامه‌ی این وضعیت بیش از شش ماه</li></ul><h2>۸ راه برخورد با کودک لجباز</h2><ol><li>وارد جنگ قدرت نشوید. در دعوای «من می‌گویم/تو می‌گویی» هیچ‌کس برنده نمی‌شود. با صدای آرام قانون را یک بار بگویید و وارد بحث نشوید.</li><li>به او حق انتخاب بدهید. «الان مسواک می‌زنی یا بعد از قصه؟» هر دو گزینه برای شما قابل قبول است، اما کودک حس می‌کند تصمیم با اوست.</li><li>درخواست را مثبت و کوتاه بگویید. به‌جای «این‌قدر روی مبل بالا و پایین نپر!» بگویید «پاها روی زمین.» جمله‌ی کوتاه و مشخص بهتر شنیده می‌شود.</li><li>احساسش را نام ببرید. «می‌دانم دلت می‌خواهد بیشتر بازی کنی و ناراحتی که باید تمام شود.» نام بردن احساس، شدتش را کم می‌کند، حتی اگر قانون عوض نشود.</li><li>از قبل خبر بدهید. تغییر ناگهانی لجبازی می‌آورد. «پنج دقیقه‌ی دیگر بازی تمام می‌شود» به کودک فرصت آماده شدن می‌دهد.</li><li>همکاری را ببینید و تشویق کنید. «ممنون که زود آمدی سر میز» خیلی بیشتر از سرزنش اثر دارد.</li><li>پیامد منطقی، نه تنبیه. اگر اسباب‌بازی را جمع نکرد، فردا آن اسباب‌بازی در دسترس نیست. آرام بگویید و اجرا کنید، بدون تحقیر یا سخنرانی.</li><li>ثابت‌قدم بمانید. اگر یک بار بعد از گریه کوتاه بیایید، کودک یاد می‌گیرد گریه‌ی بیشتر جواب می‌دهد.</li></ol><p>برگردیم به سارا و پدرش. با کمک مشاور، یک «جدول شب» با تصویر ساختند: حمام، پیژامه، مسواک، قصه. سارا خودش هر مرحله را علامت می‌زد. چون کنترل در دست خودش بود، دیگر دلیلی برای جنگیدن نداشت. بعد از دو هفته، زمان خوابیدن از یک ساعت به بیست دقیقه رسید.</p><p>البته شب‌های سخت هنوز بود. یک شب سارا گفت امشب پیژامه نمی‌پوشد. پدرش، که قبلاً در چنین موقعیتی صدایش را بالا می‌برد، این بار آرام گفت: «باشه، پیژامه‌ی خرسی یا ستاره‌ای؟» سارا لحظه‌ای فکر کرد و خرسی را برداشت. پدر بعدها گفت آن شب فهمید سارا با «پیژامه» مخالف نبود؛ با «دستور» مخالف بود. او همچنین یاد گرفت وقتی سارا خسته است، انتظاراتش را کمی پایین بیاورد و به‌جای بحث، کنارش بنشیند. مادر سارا هم همین روش را در پیش گرفت تا قانون‌ها بین دو والد یکسان باشد. هماهنگی والدین به سارا نشان داد که اصرار بیشتر، قانون را عوض نمی‌کند.</p><p>یک تمرین برای همین هفته: سه موقعیتی را که بیشترین لجبازی را دارند، مثل خواب، غذا یا بیرون رفتن، بنویسید. برای هرکدام دو گزینه آماده کنید که هر دو برای شما قابل قبول باشد. این هفته در همان موقعیت‌ها به‌جای دستور، این دو گزینه را پیشنهاد دهید و یادداشت کنید چند بار درگیری پیش آمد. معمولاً همین تغییر کوچک، تعداد دعواها را محسوس کم می‌کند و به شما هم نشان می‌دهد کودکتان بیشتر از آنچه فکر می‌کردید اهل همکاری است.</p><h2>باورهای نادرست رایج درباره‌ی لجبازی کودک</h2><p>«باید غرورش را بشکنم تا یاد بگیرد.» شکستن کودک او را مطیع نمی‌کند؛ یا ترسو می‌کند یا خشمگین‌تر. هدف هدایت اراده‌ی کودک است، نه نابود کردن آن.</p><p>«اگر کوتاه بیایم، باخته‌ام.» فرزندپروری مسابقه نیست. گاهی انعطاف در موضوع‌های کم‌اهمیت، انرژی شما را برای قانون‌های مهم‌تر نگه می‌دارد.</p><p>«کودک لجباز بعداً آدم سرکشی می‌شود.» همان ویژگی‌ای که امروز لجبازی به نظر می‌رسد، اگر درست هدایت شود، فردا می‌تواند به پشتکار، استقلال و رهبری تبدیل شود.</p><p>«توضیح دادن به بچه فایده‌ای ندارد.» توضیح کوتاه و ساده درباره‌ی دلیل قانون، همکاری را بیشتر می‌کند. اما سخنرانی‌های طولانی، به‌خصوص وسط دعوا، معمولاً شنیده نمی‌شوند.</p><p>«لجبازی فقط برای اذیت کردن من است.» بیشتر وقت‌ها لجبازی ربطی به آزار والد ندارد؛ کودک دارد استقلال را تمرین می‌کند یا نیازی را نشان می‌دهد که نمی‌تواند به زبان بیاورد.</p><p>«یک روش را چند روز امتحان کردم و جواب نداد.» تغییر رفتار کودک معمولاً چند هفته ثبات می‌خواهد. حتی گاهی رفتار قبل از بهتر شدن کمی بدتر می‌شود، چون کودک مرزهای تازه را امتحان می‌کند.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر لجبازی شدید و همیشگی است، با پرخاشگری همراه است، در مدرسه و جمع هم دیده می‌شود، یا رابطه‌ی شما با کودک را فرسوده کرده، با روان‌شناس کودک مشورت کنید. آموزش مدیریت رفتار به والدین یکی از درمان‌های مؤثر برای رفتارهای مقابله‌ای شدید است و گاهی مشکلاتی مثل بیش‌فعالی یا اضطراب پشت لجبازی پنهان‌اند. برای مشاوره، با مرکز مشاوره‌ی انتخاب بهتر به شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>لجبازی کودک ۲ تا ۳ ساله طبیعی است؟</h3><p>بله، در این سن «نه» گفتن بخشی از رشد استقلال است. هدف حذف آن نیست، هدایت آن است.</p><h3>آیا نادیده گرفتن لجبازی کار درستی است؟</h3><p>برای رفتارهای کوچک توجه‌طلبانه بله، اما قانون‌های ایمنی و اصلی باید با آرامش اجرا شوند.</p><h3>چرا کودکم فقط با من لجبازی می‌کند؟</h3><p>اغلب کودکان با کسی که بیشترین احساس امنیت را با او دارند، احساسات سختشان را بیشتر بروز می‌دهند. این نشانه‌ی شکست شما نیست.</p><h2>جمع‌بندی</h2><p>لجبازی کودک معمولاً نیاز او به کنترل و دیده شدن است. وقتی از جنگ قدرت بیرون بیایید، به او انتخاب‌های کوچک بدهید و قانون‌ها را آرام و ثابت نگه دارید، «نه»‌ها کم‌کم جایشان را به همکاری می‌دهند.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/93/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%B4%DB%8C%D9%88%D9%87-%D9%87%D8%A7%DB%8C-%D9%81%D8%B1%D8%B2%D9%86%D8%AF%D9%BE%D8%B1%D9%88%D8%B1%DB%8C-%D8%A8%D8%A7%D9%85%D8%B1%DB%8C%D9%86%D8%AF" target="_blank" rel="noopener">پرسشنامه شیوه‌های فرزندپروری بامریند</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/336/%D8%AD%D8%AF-%D9%88-%D9%85%D8%B1%D8%B2-%D8%AF%D8%B1-%D8%AE%D8%A7%D9%86%D9%88%D8%A7%D8%AF%D9%87" target="_blank" rel="noopener">حد و مرز در خانواده</a> | <a href="https://www.betterchoice.ir/fa/edu/567/%DA%AF%D9%81%D8%AA%DA%AF%D9%88%DB%8C-%D9%85%D9%88%D8%AB%D8%B1-%D8%AF%D8%B1-%D8%AE%D8%A7%D9%86%D9%88%D8%A7%D8%AF%D9%87" target="_blank" rel="noopener">گفتگوی موثر در خانواده</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6497/%D8%AA%D9%81%D8%A7%D9%88%D8%AA_%D9%BE%DB%8C%D8%A7%D9%85%D8%AF_%D9%88_%D8%AA%D9%86%D8%A8%DB%8C%D9%87" target="_blank" rel="noopener">تفاوت پیامد و تنبیه</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6631" target="_blank" rel="noopener">مربیگری هیجانات، قدم سوم: پرداختن به هیجانات کودک با گوش دادن و تأیید همدلانه</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6734/%DB%B1%DB%B0_%D9%86%DA%A9%D8%AA%D9%87_%D9%85%D9%87%D9%85_%D8%A8%D8%B1%D8%A7%DB%8C_%D8%A2%D9%85%D9%88%D8%B2%D8%B4_%D8%AC%D8%B1%D8%A7%D8%AA%D9%85%D9%86%D8%AF%DB%8C_%D8%A8%D9%87_%D9%81%D8%B1%D8%B2%D9%86%D8%AF%D8%A7%D9%86%D8%AA%D8%A7%D9%86" target="_blank" rel="noopener">۱۰ نکته مهم برای آموزش جراتمندی به فرزندانتان</a></p></div>','["Psych Central. 4 ways to manage oppositional defiant disorder in children. https://psychcentral.com/blog/4-ways-to-manage-oppositional-defiant-disorder-in-children", "Psych Central. Treating ODD: What are my options? https://psychcentral.com/disorders/oppositional-defiant-disorder-symptoms/oppositional-defiant-disorder-treatment", "Larzelere, R. E., &amp; Knowles, S. J. (2015, August). Toddlers need both positive parenting and consistent consequences from mothers [Conference presentation summary]. Annual Convention of the American Psychological Association, Toronto. https://www.apa.org/news/press/releases/2015/08/toddlers-parenting.pdf", "Centers for Disease Control and Prevention. Tips for redirecting your attention. https://www.cdc.gov/parenting-toddlers/responding-to-behavior/ignoring.html"]'::jsonb,false,true),
('a6','زخم‌های کودکی: چطور گذشته در رابطه‌های امروز تکرار می‌شود؟','بعضی وقت‌ها در رابطه‌ها واکنشی نشان می‌دهیم که خودمان هم از شدتش تعجب می‌کنیم: یک پیام بی‌جواب ما را به وحشت می‌اندازد، یک انتقاد کوچک ما را خرد می‌کند، یا بارها و بارها جذب آدم‌هایی می‌شویم که ما را نادیده می‌گیرند. اغلب، ریشه‌ی این واکنش‌ها در گذشته است. زخم‌های کودکی، یعنی تجربه‌های دردناکی که در سال‌های رشد از سر گذرانده‌ایم، گاهی بی‌آنکه بدانیم، در رابطه‌های بزرگسالی‌مان تکرار می‌شوند. این مقاله با قصه‌ی زنی شروع می‌شود که سومین رابطه‌اش هم به همان جای آشنا رسید.','self',7,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۶','img/articles/a6-cover.jpg','img/articles/a6-thumb.jpg','<h2>قصه‌ی مهسا: سومین بار، همان داستان</h2><p>مهسا سی‌وچهار سال دارد و طراح گرافیک است. آدم خوش‌رو و پرانرژی‌ای است و دوستانش او را «دلگرمی جمع» می‌دانند. اما رابطه‌های عاطفی‌اش، یکی پس از دیگری، به یک نقطه رسیده‌اند.</p><p>اولی، در دانشگاه، پسری بود که هفته‌ها غیب می‌شد و بعد با یک پیام کوتاه برمی‌گشت. دومی، همکاری بود که بعد از دو سال گفت «آماده‌ی تعهد نیست». و حالا سومی، کامران: مردی جذاب و موفق که وقتی بود، دنیا را به پای مهسا می‌ریخت، اما وقتی سرش شلوغ می‌شد، روزها جواب پیام‌هایش را نمی‌داد.</p><p>آن شب جمعه، کامران قرار بود ساعت هشت بیاید. ساعت نه شد. ده شد. مهسا پنج بار زنگ زد و دوازده پیام فرستاد. با هر دقیقه، سینه‌اش تنگ‌تر می‌شد. فکرها مثل سیل می‌آمدند: «حتماً از من خسته شده. حتماً یکی دیگه رو پیدا کرده. من هیچ‌وقت برای کسی کافی نیستم.»</p><p>ساعت یازده، کامران پیام داد: «ببخش، جلسه طول کشید، گوشیم خاموش بود. فردا می‌بینمت.»</p><p>مهسا باید آرام می‌شد، اما نشد. گریه کرد، بعد عصبانی شد و پیام بلندی نوشت که پشیمانش کرد. کامران فقط جواب داد: «من نمی‌تونم با این حجم از اضطراب کنار بیام.»</p><p>مهسا تا صبح بیدار ماند. نزدیک سحر، تصویری قدیمی در ذهنش آمد: خودش، هفت‌ساله، پشت پنجره‌ی خانه‌ی مادربزرگ، منتظر پدری که قول داده بود جمعه بیاید. پدر و مادرش وقتی او پنج‌ساله بود جدا شده بودند. پدر گاهی می‌آمد، گاهی نه. هیچ‌وقت هم توضیح نمی‌داد. مهسا یاد گرفته بود که اگر دختر خیلی خوبی باشد، شاید دفعه‌ی بعد پدر بیاید.</p><p>برای اولین بار، مهسا شباهت را دید. «من دارم همون انتظار رو تکرار می‌کنم. همیشه عاشق کسایی می‌شم که نمیان.»</p><p>صبح، به دوستش شیرین زنگ زد. شیرین، که خودش چند سال روان‌درمانی رفته بود، گفت: «مهسا، این ضعف تو نیست. این زخمیه که هنوز خوب نشده. ولی می‌شه روش کار کرد.»</p><p>مهسا آن روز اولین جلسه‌ی مشاوره‌اش را رزرو کرد.</p><h2>از کجا بفهمم زخم‌های کودکی در رابطه‌هایم تکرار می‌شوند؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند الگوهایتان را بهتر ببینید.</p><ol><li>آیا مدام جذب آدم‌هایی می‌شوید که از نظر عاطفی در دسترس نیستند؟</li><li>آیا واکنش‌هایتان در رابطه، مثلاً به دیر جواب دادن، گاهی خیلی شدیدتر از خود ماجراست؟</li><li>آیا رابطه‌هایتان، با آدم‌های متفاوت، به پایان‌های شبیه هم می‌رسند؟</li><li>آیا احساس می‌کنید برای دوست داشته شدن باید «کافی» یا «بی‌نقص» باشید؟</li><li>آیا از نزدیکی زیاد می‌ترسید و وقتی کسی خیلی نزدیک می‌شود، فاصله می‌گیرید؟</li><li>آیا در کودکی جدایی، بی‌توجهی، تحقیر یا خشونت را تجربه کرده‌اید؟</li></ol><h2>زخم‌های کودکی چیست و چرا تکرار می‌شوند؟</h2><p>زخم‌های کودکی فقط اتفاق‌های بزرگ و آشکار نیستند. کنار آزار و خشونت، تجربه‌هایی مثل بی‌توجهی عاطفی، جدایی پدر و مادر، اعتیاد یا بیماری روانی یکی از والدین، و بزرگ شدن در خانه‌ای پرتنش هم ردی ماندگار می‌گذارند. این تجربه‌ها رایج‌اند. بر پایه‌ی گزارش مراکز کنترل و پیشگیری بیماری آمریکا، که داده‌های سال‌های ۲۰۱۱ تا ۲۰۲۰ را بررسی کرده، حدود ۶۴ درصد بزرگسالان دست‌کم یک تجربه‌ی ناگوار کودکی و حدود ۱۷ درصد چهار تجربه یا بیشتر را گزارش کرده‌اند.</p><p>اما چرا این زخم‌ها در رابطه‌های امروز تکرار می‌شوند؟ روان‌شناسان از پدیده‌ای به نام «اجبار به تکرار» حرف می‌زنند: گرایش ناآگاهانه به بازآفرینی موقعیت‌هایی شبیه درد گذشته. به گفته‌ی لیندا اسپوزیتو، روان‌درمانگر، ممکن است امید داشته باشیم این بار بر آنچه در کودکی کنترلش را نداشتیم مسلط شویم، یا باور کرده باشیم که سزاوار بدرفتاری هستیم؛ و مهم‌تر از همه، الگوی آشنا، حتی اگر دردناک باشد، از ناشناخته‌ی امن، قابل‌پیش‌بینی‌تر به نظر می‌رسد.</p><p>پژوهش کلاسیک هازان و شیور هم نشان داد که سه سبک اصلی دلبستگی کودکی، یعنی ایمن، اضطرابی و اجتنابی، در شیوه‌ی عاشق شدن بزرگسالان هم دیده می‌شوند؛ و کسانی که سبک دلبستگی متفاوتی داشتند، رابطه با پدر و مادرشان را هم متفاوت به یاد می‌آوردند.</p><h2>نشانه‌های تکرار زخم‌های کودکی در رابطه</h2><ul><li>جذب شدن مکرر به آدم‌های سرد، دور یا ناپایدار</li><li>ترس شدید از رها شدن و نیاز مداوم به اطمینان</li><li>ترس از نزدیکی و فرار از صمیمیت</li><li>واکنش‌های شدید و ناگهانی به اتفاق‌های کوچک</li><li>احساس اینکه «کافی نیستم» و تلاش برای جلب رضایت</li><li>ماندن در رابطه‌های آسیب‌زا، با این امید که طرف عوض شود</li><li>تکرار رفتارهای پدر یا مادر، با وجود قول به خود که «مثل او نمی‌شوم»</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>الگو را ببینید، نه فقط آدم‌ها را. رابطه‌های گذشته‌تان را کنار هم بنویسید: چه چیزی جذبتان کرد؟ چطور تمام شد؟ چه حسی آشنا بود؟ دیدن الگو، اولین قدم برای شکستن آن است.</li><li>گذشته را در زمان خودش بگذارید. وقتی واکنشی شدید دارید، بپرسید: «این حس چند سال دارد؟» گاهی کسی که الان می‌ترسد، کودک هفت‌ساله‌ای است که پشت پنجره منتظر است، نه بزرگسال امروز.</li><li>آرام کردن خودتان را یاد بگیرید. تنفس آهسته، ذهن‌آگاهی و نام‌گذاری احساس، کمک می‌کنند در لحظه‌ی برانگیختگی، به‌جای واکنش، پاسخ دهید.</li><li>به «آشنا» شک کنید. اگر کسی به‌شدت جذابتان کرد و حسی آشنا داشت، کمی آهسته‌تر پیش بروید و ببینید آیا او همان الگوی قدیمی را تکرار می‌کند.</li><li>رابطه‌ای امن را تجربه کنید. رابطه‌ی درمانی، دوستی‌های پایدار یا شریکی که قابل اعتماد است، می‌تواند کم‌کم تجربه‌ی تازه‌ای از امنیت بسازد.</li><li>با خودتان مهربان باشید. این الگوها روزی برای بقا ساخته شده‌اند. سرزنش، زخم را عمیق‌تر می‌کند؛ شفقت، راه ترمیم را باز می‌کند.</li></ol><p>و مهسا؟ در جلسه‌های درمان، مهسا کم‌کم دید که کامران، و پیش از او دو نفر دیگر، چقدر شبیه پدرش بودند: گرم و دلفریب، اما غیرقابل‌پیش‌بینی. یاد گرفت وقتی اضطراب بالا می‌گیرد، پیش از فرستادن پیام، ده دقیقه صبر کند، نفس بکشد و از خودش بپرسد: «الان من سی‌وچهارساله‌ام یا هفت‌ساله؟» رابطه با کامران تمام شد؛ این بار نه با دعوا، بلکه با این جمله‌ی مهسا: «من کسی رو می‌خوام که بیاد، نه کسی که منتظرش بمونم.» یک سال بعد، با مردی آشنا شد که به نظرش «زیادی آرام» و حتی کمی کسل‌کننده بود. به درمانگرش گفت: «فکر کنم این حس کسل‌کننده، اسم دیگه‌ی امنیته.»</p><h2>باورهای نادرست رایج درباره‌ی زخم‌های کودکی</h2><p>«گذشته گذشته؛ ربطی به امروز ندارد.» تجربه‌های اولیه الگوهای ما را در دلبستگی و رابطه شکل می‌دهند و تا وقتی دیده نشوند، ادامه پیدا می‌کنند.</p><p>«فقط آزار شدید زخم می‌سازد.» بی‌توجهی عاطفی، تحقیر مداوم و ناپایداری خانواده هم می‌توانند اثرهای ماندگار داشته باشند.</p><p>«اگر کودکی سختی داشته‌ام، محکوم به رابطه‌های بدم.» الگوها قابل‌تغییرند؛ آگاهی، رابطه‌های امن و درمان، مسیر را عوض می‌کنند.</p><p>«باید پدر و مادرم را مقصر بدانم تا خوب شوم.» درمان درباره‌ی فهمیدن است، نه سرزنش. می‌شود درد را دید بی‌آنکه زندگی را صرف مقصر دانستن کرد.</p><p>«با یک رابطه‌ی عاشقانه‌ی خوب، زخم‌ها خودشان خوب می‌شوند.» رابطه‌ی امن کمک می‌کند، اما کار درونی روی الگوها هم لازم است.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر رابطه‌هایتان مدام به پایان‌های دردناک و شبیه هم می‌رسند، اگر اضطراب یا خشم در رابطه از کنترلتان خارج می‌شود، اگر خاطره‌های کودکی هنوز آزارتان می‌دهند، یا اگر در رابطه‌ای آسیب‌زا گیر افتاده‌اید، وقت کمک گرفتن است. برای رزرو جلسه با روان‌شناسان مرکز مشاوره‌ی انتخاب بهتر با شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>چرا همیشه عاشق آدم‌های اشتباه می‌شوم؟</h3><p>گاهی چون «آشنا» را با «درست» اشتباه می‌گیریم. آدمی که حسی شبیه کودکی‌مان می‌دهد، جذاب‌تر به نظر می‌رسد، حتی اگر دردناک باشد.</p><h3>آیا زخم‌های کودکی درمان می‌شوند؟</h3><p>بله. روان‌درمانی، رابطه‌های امن و تمرین مهارت‌های تنظیم هیجان، به بسیاری از افراد کمک کرده الگوهای قدیمی را بشکنند.</p><h3>از کجا بدانم واکنشم به گذشته مربوط است؟</h3><p>اگر شدت واکنش خیلی بیشتر از ماجراست و حسی قدیمی و آشنا دارد، احتمالاً گذشته در آن نقش دارد.</p><h2>جمع‌بندی</h2><p>زخم‌های کودکی رایج‌اند و گاهی بی‌صدا، در انتخاب‌ها و واکنش‌های عاشقانه‌مان تکرار می‌شوند. دیدن الگو، گذاشتن گذشته در زمان خودش، آرام کردن خود و تجربه‌ی رابطه‌های امن، راه شکستن این چرخه است. گذشته را نمی‌شود تغییر داد، اما می‌شود نگذاشت که آینده را هم بنویسد.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/114/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%B7%D8%B1%D8%AD%D9%88%D8%A7%D8%B1%D9%87-%D9%87%D8%A7%DB%8C-%D9%86%D8%A7%D8%B3%D8%A7%D8%B2%DA%AF%D8%A7%D8%B1-%D8%A7%D9%88%D9%84%DB%8C%D9%87" target="_blank" rel="noopener">پرسشنامه طرحواره‌های ناسازگار اولیه</a>، <a href="https://www.betterchoice.ir/fa/qdetail/13/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%B3%D8%A8%DA%A9-%D8%AF%D9%84%D8%A8%D8%B3%D8%AA%DA%AF%DB%8C-%DA%A9%D9%88%D9%84%DB%8C%D9%86%D8%B2-%D9%88-%D8%B1%DB%8C%D8%AF" target="_blank" rel="noopener">مقیاس سبک دلبستگی کولینز و رید</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/772/%D8%A7%D8%B2-%D8%AF%D9%84-%D8%A7%D9%88-%D8%AA%D8%A7-%D8%AF%D9%84-%D9%85%D9%86--%D8%B1%D9%87%D8%A7%DB%8C%DB%8C-%D8%A7%D8%B2-%D9%85%DB%8C%D8%B1%D8%A7%D8%AB-%D9%87%DB%8C%D8%AC%D8%A7%D9%86%DB%8C-%D8%AE%D8%A7%D9%86%D9%87-%D9%BE%D8%AF%D8%B1%DB%8C" target="_blank" rel="noopener">از دل او تا دل من (رهایی از میراث هیجانی خانه پدری)</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6819/%D8%B1%D9%88%D8%A7%D9%86%E2%80%8C%D8%B2%D8%AE%D9%85%E2%80%8C%D9%87%D8%A7%DB%8C_%D8%AF%D9%88%D8%B1%D8%A7%D9%86_%DA%A9%D9%88%D8%AF%DA%A9%DB%8C_%DA%86%D8%B7%D9%88%D8%B1_%D8%B1%D9%88%DB%8C_%D8%B1%D9%88%D8%A7%D8%A8%D8%B7_%D8%AF%D9%88%D8%B1%D8%A7%D9%86_%D8%A8%D8%B2%D8%B1%DA%AF%D8%B3%D8%A7%D9%84%DB%8C_%D8%A7%D8%AB%D8%B1_%D9%85%DB%8C%E2%80%8C%DA%AF%D8%B0%D8%A7%D8%B1%D8%AF_%D9%82%D8%B3%D9%85%D8%AA_%D8%A7%D9%88%D9%84" target="_blank" rel="noopener">روان‌زخم‌های دوران کودکی چطور روی روابط دوران بزرگسالی اثر می‌گذارد – قسمت اول</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6745/%DA%86%D8%B7%D9%88%D8%B1_%D8%AE%D9%88%D8%AF%D9%85%D8%A7%D9%86_%D8%B1%D8%A7_%D8%A7%D8%B2_%D8%A2%D8%B3%DB%8C%D8%A8%E2%80%8C%D9%87%D8%A7%DB%8C_%DA%AF%D8%B0%D8%B4%D8%AA%D9%87_%D8%AC%D8%AF%D8%A7_%DA%A9%D9%86%DB%8C%D9%85" target="_blank" rel="noopener">چطور خودمان را از آسیب‌های گذشته جدا کنیم</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6549" target="_blank" rel="noopener">چگونه از آسیب‌های روابط گذشته بهبود یابیم؟</a></p></div>','["Esposito, L. (2016, March 22). Why do we repeat the past in our relationships? Psychology Today. https://www.psychologytoday.com/us/blog/anxiety-zen/201603/why-do-we-repeat-the-past-in-our-relationships", "Hazan, C., &amp; Shaver, P. (1987). Romantic love conceptualized as an attachment process. Journal of Personality and Social Psychology, 52(3), 511–524. https://pubmed.ncbi.nlm.nih.gov/3572722/", "Swedo, E. A., Aslam, M. V., Dahlberg, L. L., Niolon, P. H., Guinn, A. S., Simon, T. R., &amp; Mercy, J. A. (2023). Prevalence of adverse childhood experiences among U.S. adults: Behavioral Risk Factor Surveillance System, 2011–2020. MMWR Morbidity and Mortality Weekly Report, 72(26), 707–715. https://pubmed.ncbi.nlm.nih.gov/37384554/"]'::jsonb,false,true),
('a7','احساس تنهایی: وقتی میان جمع هم تنهاییم','تنهایی همیشه به معنای تنها بودن نیست. می‌شود در خانه‌ای شلوغ، در محل کاری پرهیاهو یا حتی کنار همسر زندگی کرد و باز احساس کرد هیچ‌کس واقعاً شما را نمی‌بیند. احساس تنهایی دردی است که از فاصله‌ی میان رابطه‌ای که می‌خواهیم و رابطه‌ای که داریم، می‌آید. این درد فقط عاطفی نیست؛ پژوهش‌ها نشان می‌دهند تنهایی بر سلامت قلب، خواب و حتی طول عمر هم اثر می‌گذارد. این مقاله با قصه‌ی مردی شروع می‌شود که همه فکر می‌کردند زندگی‌اش کامل است.','mental',6,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۷','img/articles/a7-cover.jpg','img/articles/a7-thumb.jpg','<h2>قصه‌ی بهروز: مهمانی‌ای که تنهاتر برگشت</h2><p>بهروز چهل‌ویک سال دارد و مدیر فروش یک شرکت بیمه است. زن و دو فرزند دارد، در یک آپارتمان خوب زندگی می‌کند و گوشی‌اش پر از پیام گروه‌های کاری و خانوادگی است. از بیرون، زندگی‌اش شلوغ و کامل به نظر می‌رسد.</p><p>آن پنجشنبه، مهمانی تولد پنجاه‌سالگی برادر بزرگش بود. خانه پر از آدم بود: عمه‌ها، پسرعموها، دوستان قدیمی. بهروز با همه دست داد، خندید و از کار و قیمت ماشین و تیم فوتبال حرف زد. اما وسط مهمانی، کنار پنجره ایستاد و به جمعیت نگاه کرد. ناگهان حسی سنگین سراغش آمد: «اینجا هیچ‌کس نمی‌دونه من واقعاً چه حالی دارم.»</p><p>یادش آمد آخرین باری که با کسی درباره‌ی چیزی غیر از کار و قسط و مدرسه‌ی بچه‌ها حرف زده، کِی بوده. نتوانست به خاطر بیاورد. دوست صمیمی دوران دانشگاهش، سعید، شش سال پیش مهاجرت کرده بود و تماس‌هایشان کم‌کم به تبریک عید محدود شده بود. با همسرش، لیلا، رابطه‌ی بدی نداشت، اما شب‌ها هر کدام در گوشی خودشان غرق بودند.</p><p>در راه برگشت، لیلا پرسید: «چرا این‌قدر ساکتی؟ مهمونی خوبی بود.»</p><p>بهروز گفت: «آره، خوب بود.» و دوباره ساکت شد.</p><p>آن شب خوابش نبرد. ساعت دو بامداد، در آشپزخانه نشسته بود و در شبکه‌های اجتماعی عکس‌های دیگران را بالا و پایین می‌کرد: سفرها، جمع‌های دوستانه، لبخندها. هر عکس حالش را بدتر می‌کرد. «همه یه کسی رو دارن. فقط منم که…»</p><p>چند هفته بود که کم‌خواب شده بود، حوصله‌ی ورزش نداشت و در جلسه‌های کاری زود عصبانی می‌شد. پزشک خانواده‌اش در چکاپ سالانه گفته بود فشار خونش کمی بالا رفته است.</p><p>لیلا ساعت سه بیدار شد و او را در آشپزخانه دید. کنارش نشست. «بهروز، چند وقته یه چیزیت هست. چی شده؟»</p><p>بهروز مدتی ساکت ماند. بعد، با صدایی که خودش هم نشناخت، گفت: «لیلا، من خیلی تنهام. نمی‌دونم چرا. همه دورم هستن، ولی انگار هیچ‌کس نیست.»</p><p>لیلا دستش را گرفت. چشم‌هایش پر از اشک شد. «منم چند وقته همین حس رو دارم. فکر می‌کردم فقط منم.»</p><p>آن شب، برای اولین بار در ماه‌ها، تا صبح با هم حرف زدند. و فردا، بهروز تصمیم گرفت درباره‌ی این حس با یک روان‌شناس هم صحبت کند.</p><h2>از کجا بفهمم احساس تنهایی دارم؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند حال خودتان را بهتر بشناسید.</p><ol><li>آیا احساس می‌کنید کسی نیست که بتوانید حرف دلتان را به او بزنید؟</li><li>آیا میان جمع هم احساس می‌کنید کسی واقعاً شما را نمی‌فهمد؟</li><li>آیا رابطه‌هایتان بیشتر سطحی‌اند تا عمیق؟</li><li>آیا بیشتر وقت آزادتان را در شبکه‌های اجتماعی می‌گذرانید و بعد حالتان بدتر می‌شود؟</li><li>آیا از دعوت‌ها و دیدارها پرهیز می‌کنید، با اینکه دلتان ارتباط می‌خواهد؟</li><li>آیا خوابتان به هم ریخته یا انرژی‌تان کم شده است؟</li></ol><h2>احساس تنهایی چیست و چرا مهم است؟</h2><p>تنهایی با تنها بودن فرق دارد. سایکولوژی تودی تنهایی را رنجی تعریف می‌کند که از فاصله‌ی میان ارتباطی که آرزو داریم و ارتباطی که تجربه می‌کنیم، پدید می‌آید؛ رنجی که حتی در ازدواج‌های طولانی یا میان جمع هم ممکن است. در مقابل، تنها بودن انتخابی می‌تواند آرامش‌بخش و الهام‌بخش باشد.</p><p>تنهایی مسئله‌ای جهانی است. کمیسیون ارتباط اجتماعی سازمان جهانی بهداشت در گزارش سال ۲۰۲۵ اعلام کرد که از هر شش نفر در جهان، یک نفر تنهایی را تجربه می‌کند و تنهایی با حدود ۸۷۱ هزار مرگ در سال مرتبط است. یک فراتحلیل بزرگ بر پایه‌ی ۱۴۸ پژوهش و بیش از ۳۰۰ هزار نفر هم نشان داد کسانی که رابطه‌های اجتماعی قوی‌تری دارند، ۵۰ درصد شانس بقای بیشتری دارند؛ اثری که پژوهشگران آن را هم‌تراز عوامل خطر شناخته‌شده‌ی مرگ دانسته‌اند.</p><p>تنهایی چرخه‌ای می‌سازد: آدم تنها، برای محافظت از خود، به نشانه‌های طرد حساس‌تر می‌شود، از جمع کناره می‌گیرد و همین کناره‌گیری، تنهایی را عمیق‌تر می‌کند.</p><h2>نشانه‌های رایج احساس تنهایی</h2><ul><li>احساس دیده نشدن یا فهمیده نشدن، حتی در جمع</li><li>نداشتن کسی برای درد دل</li><li>خستگی، بی‌حوصلگی و کم‌خوابی</li><li>حساسیت بیشتر به طرد یا بی‌اعتنایی دیگران</li><li>پناه بردن به شبکه‌های اجتماعی، تلویزیون یا کار زیاد</li><li>کناره‌گیری از دیدارها، با وجود دلتنگی برای ارتباط</li><li>غم، تحریک‌پذیری یا احساس پوچی</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>اسمش را بگذارید. گفتن «من احساس تنهایی می‌کنم» شرم ندارد. تنهایی یک نیاز است، مثل گرسنگی؛ پیامی که می‌گوید به ارتباط بیشتری نیاز داریم.</li><li>کیفیت را به کمیت ترجیح دهید. یک گفتگوی عمیق با یک نفر، بیشتر از ده پیام در گروه کمک می‌کند. یک یا دو رابطه را انتخاب کنید و روی آن‌ها سرمایه‌گذاری کنید.</li><li>قدم‌های کوچک و منظم بردارید. هفته‌ای یک تماس با دوستی قدیمی، یک قرار قهوه یا یک پیاده‌روی با همکار. همان‌طور که ورزش عضله می‌سازد، این قدم‌ها هم توان ارتباطی را تقویت می‌کنند.</li><li>فکرهای طردکننده را بررسی کنید. وقتی ذهن می‌گوید «حتماً حوصله‌ی من رو نداره»، بپرسید: «شاهدش چیه؟ شاید اونم منتظر تماس منه.»</li><li>به جمعی با هدف مشترک بپیوندید. کلاس، گروه کوهنوردی، کار داوطلبانه یا دوره‌ی آموزشی، ارتباط را طبیعی‌تر می‌کند، چون تمرکز روی فعالیت است، نه روی خود ارتباط.</li><li>زمان صفحه‌ی نمایش را محدود کنید. شبکه‌های اجتماعی جای ارتباط واقعی را نمی‌گیرند و مقایسه با زندگی دیگران، تنهایی را بیشتر می‌کند.</li></ol><p>و بهروز؟ در جلسه‌های مشاوره، بهروز دید که سال‌ها همه‌ی انرژی‌اش را صرف کار و تأمین خانواده کرده و دوستی‌ها را «برای بعد» گذاشته است. اولین قدمش ساده بود: یک تماس تصویری با سعید. قرار بود ده دقیقه باشد، اما دو ساعت طول کشید و هر دو خندیدند و حتی کمی گریه کردند. بعد، با لیلا قرار گذاشتند هر شب، نیم ساعت گوشی‌ها را کنار بگذارند و فقط با هم حرف بزنند. بهروز به یک گروه کوهنوردی جمعه‌ها هم پیوست. چند ماه بعد، به روان‌شناسش گفت: «هنوز گاهی تنهام. ولی حالا می‌دونم کجا برم، به کی زنگ بزنم.» فشار خونش هم در چکاپ بعدی پایین‌تر آمده بود.</p><h2>باورهای نادرست رایج درباره‌ی احساس تنهایی</h2><p>«تنهایی یعنی تنها زندگی کردن.» بسیاری از آدم‌های تنها، متأهل‌اند و میان جمع زندگی می‌کنند؛ تنهایی به کیفیت رابطه‌ها مربوط است.</p><p>«تنهایی فقط مال سالمندان است.» سازمان جهانی بهداشت تأکید دارد که تنهایی میان جوانان هم بسیار شایع است.</p><p>«تنهایی فقط یک حس است و به سلامت ربطی ندارد.» تنهایی با بیماری قلبی، افسردگی، کم‌خوابی و حتی مرگ زودرس مرتبط است.</p><p>«کسی که احساس تنهایی می‌کند، حتماً مشکل شخصیتی دارد.» تنهایی تجربه‌ای انسانی است و اغلب از تغییرهای زندگی، مثل مهاجرت، بازنشستگی یا فقدان، می‌آید.</p><p>«دوستان مجازی کافی‌اند.» ارتباط مجازی می‌تواند کمک کند، اما جای گفتگوی رودررو و حضور واقعی را نمی‌گیرد.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر احساس تنهایی هفته‌هاست ادامه دارد، اگر با غم عمیق، ناامیدی یا بی‌لذتی همراه شده، اگر خواب و کارتان را به هم ریخته، یا اگر فکرهای آسیب به خود دارید، حتماً کمک بگیرید. تنهایی و افسردگی اغلب دست در دست هم می‌آیند. برای رزرو جلسه با روان‌شناسان مرکز مشاوره‌ی انتخاب بهتر با شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>چرا در جمع هم احساس تنهایی می‌کنم؟</h3><p>چون تنهایی به عمق ارتباط مربوط است، نه تعداد آدم‌ها. اگر کسی شما را واقعاً نشناسد، حضورش تنهایی را برطرف نمی‌کند.</p><h3>تنهایی و افسردگی چه فرقی دارند؟</h3><p>تنهایی حس کمبود ارتباط است؛ افسردگی اختلالی گسترده‌تر با غم، بی‌لذتی و تغییر خواب و اشتهاست. این دو می‌توانند همدیگر را تشدید کنند.</p><h3>چطور دوست تازه پیدا کنم؟</h3><p>در فعالیت‌های گروهی منظم شرکت کنید، دیدارها را تکرار کنید و کم‌کم از خودتان بگویید. دوستی با زمان و تکرار ساخته می‌شود.</p><h2>جمع‌بندی</h2><p>احساس تنهایی دردی شایع و جدی است که از فاصله‌ی میان رابطه‌ی خواستنی و رابطه‌ی واقعی می‌آید و بر جسم و روان اثر می‌گذارد. شکستن این چرخه با قدم‌های کوچک ممکن است: نام گذاشتن بر حس، سرمایه‌گذاری روی چند رابطه‌ی عمیق، پیوستن به جمع‌های هدفمند و کم کردن مقایسه‌های مجازی. تنهایی پیام است، نه حکم.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/27/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3-%D8%AA%D9%86%D9%87%D8%A7%DB%8C%DB%8C--UCLA-" target="_blank" rel="noopener">مقیاس احساس تنهایی (UCLA)</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/809/%D9%85%D8%B9%D8%AC%D9%88%D9%86-%D8%B1%D8%A7%D8%A8%D8%B7%D9%87-%D9%87%D8%A7" target="_blank" rel="noopener">معجون رابطه ها</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6666/%D9%86%D9%88%D8%B9_%D8%AA%D8%A7%D8%B2%D9%87%E2%80%8C%D8%A7%DB%8C_%D8%A7%D8%B2_%D8%AA%D9%86%D9%87%D8%A7%DB%8C%DB%8C_%D8%AF%D8%B1%DA%A9_%D9%88_%D8%AA%D8%AD%D9%84%DB%8C%D9%84_%D8%A7%D8%B2_%D8%AF%D8%B3%D8%AA_%D8%AF%D8%A7%D8%AF%D9%86_%D8%B1%D9%88%D8%A7%D8%A8%D8%B7_%D9%85%D8%B9%D9%86%D8%A7%D8%AF%D8%A7%D8%B1" target="_blank" rel="noopener">نوع تازه‌ای از تنهایی (درک و تحلیل از دست دادن روابط معنادار)</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6490/%D8%AA%D9%86%D9%87%D8%A7_%D8%A8%D9%88%D8%AF%D9%86_%D8%A8%D8%AF%D9%88%D9%86_%D8%A7%D8%AD%D8%B3%D8%A7%D8%B3_%D8%AA%D9%86%D9%87%D8%A7%DB%8C%DB%8C" target="_blank" rel="noopener">تنها بودن؛ بدون احساس تنهایی</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6650" target="_blank" rel="noopener">۵ راهنمایی برای زنده نگه داشتن دوستی</a></p></div>','["Holt-Lunstad, J., Smith, T. B., &amp; Layton, J. B. (2010). Social relationships and mortality risk: A meta-analytic review. PLoS Medicine, 7(7), e1000316. https://pubmed.ncbi.nlm.nih.gov/20668659/", "Psychology Today. Loneliness. https://www.psychologytoday.com/us/basics/loneliness", "World Health Organization. (2025, June 30). Social connection linked to improved health and reduced risk of early death [News release]. https://www.who.int/news/item/30-06-2025-social-connection-linked-to-improved-heath-and-reduced-risk-of-early-death"]'::jsonb,false,true),
('a8','رفتار با نوجوان: از جنگ قدرت تا گفتگو','یک روز صبح بیدار می‌شوید و می‌بینید کودک مهربانی که دنبالتان در خانه می‌دوید، جایش را به نوجوانی داده که در اتاقش را می‌بندد، با یک کلمه جواب می‌دهد و هر نصیحتی را با چشم‌غره پس می‌زند. رفتار با نوجوان برای بسیاری از پدر و مادرها سخت‌ترین مرحله‌ی فرزندپروری است؛ مرحله‌ای که روش‌های قدیمی دیگر جواب نمی‌دهند و هر قانونی به جنگ قدرت می‌کشد. اما نوجوانی دوره‌ی طبیعی جدا شدن و ساختن هویت است و با شناخت بهتر آن، می‌شود به‌جای جنگ، گفتگو را انتخاب کرد. این مقاله با قصه‌ی مادری شروع می‌شود که دیگر دخترش را نمی‌شناخت.','parenting',7,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۸','img/articles/a8-cover.jpg','img/articles/a8-thumb.jpg','<h2>قصه‌ی زهره و دخترش رها: دری که بسته ماند</h2><p>زهره چهل‌وسه سال دارد و پرستار است. دخترش، رها، پانزده‌ساله است. تا دو سال پیش، رها هر روز از مدرسه که برمی‌گشت، همه چیز را برای مادرش تعریف می‌کرد. با هم آشپزی می‌کردند، فیلم می‌دیدند و رها روی شانه‌ی مادرش خوابش می‌برد.</p><p>حالا رها بیشتر وقتش را در اتاقش می‌گذراند، با هدفون و گوشی. سر شام، به پرسش‌های مادرش با «خوب بود» و «نمی‌دونم» جواب می‌دهد. موهایش را رنگ کرده، با دوستانی می‌گردد که زهره نمی‌شناسدشان و نمره‌هایش پایین آمده است.</p><p>آن شب پنجشنبه، رها ساعت ده و نیم به خانه رسید؛ قرار بود نه خانه باشد. زهره، که یک ساعت تمام به گوشی خاموش او زنگ زده و از نگرانی دیوانه شده بود، در را که باز کرد، فریاد زد: «کجا بودی؟ می‌دونی ساعت چنده؟ دیگه حق نداری با این دوستات بری بیرون!»</p><p>رها با صدای بلندتر جواب داد: «همیشه همینه! تو اصلاً به من اعتماد نداری! با من مثل بچه‌ی پنج‌ساله رفتار می‌کنی!»</p><p>«چون مثل بچه رفتار می‌کنی! گوشیت رو بده ببینم.»</p><p>«عمراً!» رها به اتاقش دوید و در را چنان کوبید که قاب عکس روی دیوار کج شد.</p><p>زهره پشت در ایستاد و در زد. «در رو باز کن!» جوابی نیامد. فقط صدای موسیقی بلند شد.</p><p>زهره به آشپزخانه رفت و نشست. دست‌هایش می‌لرزید. همسرش، حمید، آمد و گفت: «بذار آروم بشه. فردا باهاش حرف می‌زنیم.» اما زهره گریه کرد. «حمید، من دارم از دستش می‌دم. انگار یه غریبه تو خونه‌مونه.»</p><p>نیمه‌شب، زهره آرام به اتاق رها رفت. در قفل نبود. رها خوابیده بود، اما بالشش خیس بود. روی میزش، دفترچه‌ای باز مانده بود. زهره نخواست بخواند، اما یک جمله، با خط درشت، به چشمش خورد: «کاش یکی فقط گوش می‌داد، بدون اینکه دعوام کنه.»</p><p>زهره روی لبه‌ی تخت نشست و مدتی به دخترش نگاه کرد. فهمید که هر دو تنها هستند؛ هر کدام در یک طرف در.</p><p>فردا صبح، زهره در محل کارش با همکارش که روان‌شناس بالینی بیمارستان بود، صحبت کرد. همکارش گفت: «زهره، چیزی که تعریف می‌کنی خیلی از خانواده‌ها تجربه می‌کنن. ولی راه داره. بیا یه وقت مشاوره خانواده بگیر.»</p><h2>از کجا بفهمم رابطه‌ام با نوجوانم در جنگ قدرت گیر کرده؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند الگوی رابطه‌تان را ببینید.</p><ol><li>آیا بیشتر گفتگوهایتان با نوجوانتان به دعوا یا قهر می‌رسد؟</li><li>آیا بیشتر حرف‌هایتان به او امر، نهی یا نصیحت است؟</li><li>آیا مدت‌هاست با هم کار لذت‌بخشی انجام نداده‌اید؟</li><li>آیا از دوستان، علاقه‌ها و دغدغه‌هایش بی‌خبرید؟</li><li>آیا قانون‌ها را بدون گفتگو با او می‌گذارید؟</li><li>آیا وقتی اشتباه می‌کند، واکنش اولتان فریاد یا تنبیه است؟</li></ol><h2>در نوجوانی چه می‌گذرد؟</h2><p>نوجوانی دوره‌ی تغییرهای گسترده در بدن، مغز، احساسات و رابطه‌هاست. مؤسسه‌ی ملی سلامت روان آمریکا توضیح می‌دهد که مغز تا اواسط یا اواخر دهه‌ی بیست زندگی به بلوغ کامل نمی‌رسد و قشر پیش‌پیشانی، بخشی که مسئول برنامه‌ریزی، اولویت‌بندی و تصمیم‌گیری است، از آخرین بخش‌هایی است که رشدش کامل می‌شود. در همین دوره، بخش‌های مرتبط با رابطه‌های اجتماعی فعال‌ترند و برای همین، دوستان و پذیرش هم‌سالان برای نوجوان اهمیتی بسیار بالا پیدا می‌کنند. خواب نوجوان هم به‌طور زیستی دیرتر می‌شود و همین، بیدار ماندن تا دیروقت را توضیح می‌دهد.</p><p>جالب است بدانیم تصور رایج که دعوای والدین و نوجوان در میانه‌ی نوجوانی به اوج می‌رسد، کاملاً دقیق نیست. یک فراتحلیل نشان داد که تعداد دعواها از اوایل تا اواخر نوجوانی کم می‌شود، اما شدت هیجانی آن‌ها، دست‌کم تا میانه‌ی نوجوانی، بیشتر می‌شود. یعنی ممکن است کمتر دعوا کنید، اما دعواها داغ‌تر باشند.</p><h2>اشتباه‌های رایج در رفتار با نوجوان</h2><ul><li>فریاد زدن و تهدید در لحظه‌ی خشم</li><li>سخنرانی و نصیحت طولانی به‌جای گوش دادن</li><li>تحقیر یا مسخره کردن ظاهر، سلیقه یا دوستان او</li><li>کنترل بیش از حد، مثل چک کردن پنهانی گوشی</li><li>مقایسه با هم‌سالان یا خواهر و برادر</li><li>قانون‌های سخت بدون توضیح یا گفتگو</li><li>قطع رابطه یا قهر طولانی به‌عنوان تنبیه</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>اول گوش دهید، بعد حرف بزنید. نوجوان وقتی حس کند شنیده می‌شود، آماده‌ی شنیدن است. سؤال باز بپرسید، بازجویی نکنید و برای قضاوت عجله نکنید.</li><li>رابطه را مقدم بر قانون بگذارید. وقت کوتاه و منظمی برای با هم بودن بگذارید که درباره‌ی درس و قانون نباشد: یک چای، یک سریال مشترک، یک رانندگی. همین لحظه‌ها اعتماد می‌سازند.</li><li>قانون‌ها را با هم بسازید. درباره‌ی ساعت برگشت، گوشی و درس، با او گفتگو کنید، دلیل‌هایتان را بگویید و نظرش را بشنوید. نوجوانی که در ساختن قانون سهم داشته، بیشتر به آن پایبند است.</li><li>رفتار را نقد کنید، نه شخصیت را. به‌جای «تو آدم بی‌مسئولیتی هستی»، بگویید: «دیر اومدی و گوشیت خاموش بود. من خیلی نگران شدم.»</li><li>استقلال را کم‌کم بدهید. در حوزه‌هایی که خطر جدی ندارند، مثل لباس یا موی سر، به انتخاب‌هایش احترام بگذارید تا در موضوع‌های مهم، حرفتان را بپذیرد.</li><li>وقتی خشمگینید، گفتگو را عقب بیندازید. بگویید: «الان خیلی عصبانی‌ام. فردا صبح درباره‌اش حرف می‌زنیم.» و واقعاً برگردید.</li></ol><p>و زهره و رها؟ در جلسه‌های مشاوره‌ی خانواده، زهره یاد گرفت پیش از هر واکنشی، اول بپرسد و گوش دهد. یک شب، به‌جای پرسیدن درباره‌ی نمره‌ها، به اتاق رها رفت و فقط گفت: «اون آهنگی که این روزا گوش می‌دی چیه؟ برای منم بذار.» رها با تعجب نگاهش کرد، اما هدفون را به او داد. آن شب نیم ساعت با هم آهنگ گوش دادند و رها برای اولین بار در ماه‌ها از دوستش گفت که پدر و مادرش در حال جدایی‌اند و او نگرانش است. بعد، با هم درباره‌ی ساعت برگشت حرف زدند. رها خودش پیشنهاد داد که اگر دیر کند، پیام بدهد. چند هفته بعد، ساعت نه و ربع پیامی آمد: «مامان، ۲۰ دقیقه دیرتر میام، با سارا هستیم.» زهره پیام را چند بار خواند و لبخند زد.</p><h2>باورهای نادرست رایج درباره‌ی نوجوانی</h2><p>«نوجوانی یعنی بحران و طوفان دائمی.» بیشتر نوجوانان این دوره را بدون مشکل جدی پشت سر می‌گذارند و به بزرگسالان سالمی تبدیل می‌شوند.</p><p>«نوجوان دیگر به پدر و مادرش نیاز ندارد.» نوجوان هنوز به حمایت و حضور والدین نیاز دارد، فقط شکل این نیاز عوض شده است.</p><p>«سخت‌گیری بیشتر، نوجوان را مطیع‌تر می‌کند.» کنترل شدید اغلب به پنهان‌کاری و فاصله‌ی بیشتر می‌رسد.</p><p>«اگر او به من گوش نمی‌دهد، پس بی‌احترام است.» جدا شدن و مخالفت، بخشی طبیعی از ساختن هویت است.</p><p>«دیر خوابیدن نوجوان تنبلی است.» تغییر ساعت زیستی خواب در نوجوانی یک واقعیت بیولوژیک است.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر نوجوانتان برای مدت طولانی گوشه‌گیر، غمگین یا بی‌انگیزه است، اگر نشانه‌هایی از مصرف مواد، آسیب به خود یا فکرهای خودکشی می‌بینید، اگر افت تحصیلی شدید دارد، یا اگر دعواهای خانه از کنترل خارج شده، حتماً کمک بگیرید. بسیاری از مشکلات روانی برای اولین بار در نوجوانی آشکار می‌شوند و تشخیص زودهنگام کمک بزرگی است. برای رزرو جلسه با روان‌شناسان مرکز مشاوره‌ی انتخاب بهتر با شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>چطور با نوجوان لجباز رفتار کنیم؟</h3><p>لجبازی اغلب واکنشی به کنترل است. با دادن حق انتخاب در محدوده‌ای امن، گفتگو درباره‌ی قانون‌ها و کم کردن جنگ قدرت، لجبازی کم‌تر می‌شود.</p><h3>آیا چک کردن گوشی نوجوان درست است؟</h3><p>چک کردن پنهانی معمولاً اعتماد را از بین می‌برد. بهتر است قانون‌های استفاده از گوشی را با هم بگذارید و فقط در صورت نگرانی جدی و آشکار، دخالت کنید.</p><h3>نوجوانم با من حرف نمی‌زند، چه کنم؟</h3><p>فرصت‌های کوتاه و بی‌فشار بسازید، مثل رانندگی یا آشپزی با هم. نوجوانان اغلب وقتی چشم در چشم نیستند، راحت‌تر حرف می‌زنند.</p><h2>جمع‌بندی</h2><p>نوجوانی دوره‌ی طبیعی ساختن هویت و جدا شدن است و مغز نوجوان هنوز در حال رشد است. گوش دادن پیش از حرف زدن، مقدم دانستن رابطه، ساختن قانون‌ها با هم، نقد رفتار به‌جای شخصیت و دادن تدریجی استقلال، راه رسیدن از جنگ قدرت به گفتگوست. نوجوانتان هنوز به شما نیاز دارد؛ فقط به شکلی تازه.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/93/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%B4%DB%8C%D9%88%D9%87-%D9%87%D8%A7%DB%8C-%D9%81%D8%B1%D8%B2%D9%86%D8%AF%D9%BE%D8%B1%D9%88%D8%B1%DB%8C-%D8%A8%D8%A7%D9%85%D8%B1%DB%8C%D9%86%D8%AF" target="_blank" rel="noopener">پرسشنامه شیوه‌های فرزندپروری بامریند</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/567/%DA%AF%D9%81%D8%AA%DA%AF%D9%88%DB%8C-%D9%85%D9%88%D8%AB%D8%B1-%D8%AF%D8%B1-%D8%AE%D8%A7%D9%86%D9%88%D8%A7%D8%AF%D9%87" target="_blank" rel="noopener">گفتگوی موثر در خانواده</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6693/%D8%A7%D8%B9%D8%AA%D9%85%D8%A7%D8%AF_%D8%A7%DB%8C%D8%AC%D8%A7%D8%AF_%DA%A9%D8%B1%D8%AF%D9%86_%D8%A8%D8%A7_%D9%86%D9%88%D8%AC%D9%88%D8%A7%D9%86" target="_blank" rel="noopener">اعتماد ایجاد کردن با نوجوان</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6703/%DB%B1%DB%B5_%D8%B2%D9%86%DA%AF_%D8%AE%D8%B7%D8%B1_%D8%AF%D8%B1_%D8%B1%D9%81%D8%AA%D8%A7%D8%B1%D9%87%D8%A7%DB%8C_%D9%86%D9%88%D8%AC%D9%88%D8%A7%D9%86_%D8%A8%D8%AE%D8%B4_%D8%A7%D9%88%D9%84" target="_blank" rel="noopener">۱۵ زنگ خطر در رفتارهای نوجوان - بخش اول</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6709/%DA%86%DB%8C%D8%B2%D9%87%D8%A7%DB%8C%DB%8C_%DA%A9%D9%87_%D9%86%D9%88%D8%AC%D9%88%D8%A7%D9%86_%D9%84%D8%A7%D8%B2%D9%85_%D8%A7%D8%B3%D8%AA_%D8%AF%D8%B1_%D9%85%D9%88%D8%B1%D8%AF_%D8%AD%D8%AF_%D9%88_%D9%85%D8%B1%D8%B2_%D8%A8%D8%AF%D8%A7%D9%86%D8%AF_%D8%A8%D8%AE%D8%B4_%D8%A7%D9%88%D9%84" target="_blank" rel="noopener">چیزهایی که نوجوان لازم است در مورد حد و مرز بداند - بخش اول</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6497/%D8%AA%D9%81%D8%A7%D9%88%D8%AA_%D9%BE%DB%8C%D8%A7%D9%85%D8%AF_%D9%88_%D8%AA%D9%86%D8%A8%DB%8C%D9%87" target="_blank" rel="noopener">تفاوت پیامد و تنبیه</a></p></div>','["Laursen, B., Coy, K. C., &amp; Collins, W. A. (1998). Reconsidering changes in parent-child conflict across adolescence: A meta-analysis. Child Development, 69(3), 817–832. https://pubmed.ncbi.nlm.nih.gov/9680687/", "National Institute of Mental Health. The teen brain: 7 things to know. https://www.nimh.nih.gov/health/publications/the-teen-brain-7-things-to-know", "Psychology Today. Adolescence. https://www.psychologytoday.com/us/basics/adolescence"]'::jsonb,false,true),
('a9','سبک‌های دلبستگی: چرا در عشق این‌طور رفتار می‌کنیم؟','چرا بعضی‌ها در رابطه آرام و مطمئن‌اند، بعضی با هر تأخیر در جواب پیام نگران می‌شوند و بعضی دیگر وقتی رابطه جدی می‌شود، عقب می‌کشند؟ بخش مهمی از جواب در سبک‌های دلبستگی است: الگوهایی که از نخستین رابطه‌هایمان با مراقبانمان شکل گرفته‌اند و در بزرگسالی، در عشق و دوستی ادامه پیدا می‌کنند. شناختن سبک دلبستگی خود و همسر، کمک می‌کند بسیاری از دعواهای تکراری را بهتر بفهمیم. این مقاله با قصه‌ی زوجی شروع می‌شود که یکی دنبال می‌کرد و دیگری فرار.','relations',7,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۰۹','img/articles/a9-cover.jpg','img/articles/a9-thumb.jpg','<h2>قصه‌ی نیلوفر و کیان: یکی می‌دوید، یکی فرار می‌کرد</h2><p>نیلوفر بیست‌ونه سال دارد و معلم زبان است. کیان، نامزدش، سی‌وسه‌ساله و معمار است. یک سال است با هم‌اند و قرار است بهار ازدواج کنند. همدیگر را دوست دارند؛ در این شکی نیست. اما یک دعوای تکراری دارند که هر بار، شکل تازه‌ای پیدا می‌کند.</p><p>آن شب جمعه هم همین‌طور شروع شد. کیان گفته بود با دوستانش فوتبال می‌رود و ساعت ده برمی‌گردد. ساعت ده و نیم، نیلوفر پیام داد: «کجایی؟» جوابی نیامد. ساعت یازده، دوباره: «چرا جواب نمی‌دی؟ نگرانتم.» ساعت یازده و ربع، سه بار زنگ زد.</p><p>کیان ساعت یازده و نیم پیام داد: «تو راهم. گوشیم تو کیفم بود.»</p><p>وقتی به خانه‌ی نیلوفر رسید، نیلوفر پشت در منتظرش بود. «چرا این‌قدر بی‌خیالی؟ نمی‌فهمی من نگران می‌شم؟ اصلاً برات مهمم؟»</p><p>کیان احساس کرد دیوارها دارند به او نزدیک می‌شوند. «نیلو، یه فوتبال بود. چرا هر چیز کوچیکی رو بزرگ می‌کنی؟ من نفس می‌خوام.»</p><p>«نفس؟ یعنی من خفه‌ات می‌کنم؟»</p><p>کیان کتش را برداشت. «من الان نمی‌تونم حرف بزنم. فردا صحبت می‌کنیم.» و رفت.</p><p>نیلوفر تا صبح نخوابید. هر بار که کیان «فاصله» می‌گرفت، ترسی آشنا در سینه‌اش بیدار می‌شد؛ ترسی که از کودکی می‌شناخت. مادرش افسردگی داشت و روزهایی بود که نیلوفر کوچک هر کاری می‌کرد، مادر از رختخواب بلند نمی‌شد. نیلوفر یاد گرفته بود که برای دیده شدن، باید بلندتر صدا بزند.</p><p>کیان هم آن شب در ماشین، مدتی بی‌هدف رانندگی کرد. حس می‌کرد هرچه نیلوفر بیشتر نزدیک می‌شود، او بیشتر خفه می‌شود. پدرش مردی سرد و سخت‌گیر بود و در خانه‌شان، گریه و درد دل «ضعف» حساب می‌شد. کیان یاد گرفته بود احساساتش را تنهایی حل کند.</p><p>فردا، کیان به خانه‌ی نیلوفر آمد. هر دو خسته بودند. نیلوفر گفت: «من نمی‌خوام اینطوری ازدواج کنیم. هر هفته همین دعوا رو داریم.»</p><p>کیان سر تکان داد. «منم نمی‌خوام. ولی نمی‌دونم چطور عوضش کنم.»</p><p>نیلوفر گفت: «یکی از همکارام می‌گفت با مشاوره‌ی پیش از ازدواج، الگوهای همدیگه رو بهتر فهمیدن. بیا امتحان کنیم.»</p><h2>از کجا بفهمم سبک دلبستگی‌ام چیست؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند الگوی خودتان را بهتر ببینید.</p><ol><li>آیا مدام نگرانید که همسرتان شما را به اندازه‌ی کافی دوست نداشته باشد یا ترکتان کند؟</li><li>آیا وقتی پیامتان بی‌جواب می‌ماند، به‌شدت مضطرب می‌شوید؟</li><li>آیا وقتی رابطه خیلی نزدیک می‌شود، احساس خفگی می‌کنید و فاصله می‌گیرید؟</li><li>آیا برایتان سخت است به همسرتان تکیه کنید یا از او کمک بخواهید؟</li><li>آیا هم نزدیکی را می‌خواهید و هم از آن می‌ترسید؟</li><li>آیا در کل، در رابطه احساس امنیت و آرامش می‌کنید؟</li></ol><h2>سبک‌های دلبستگی چیست و از کجا می‌آید؟</h2><p>نظریه‌ی دلبستگی را جان بالبی مطرح کرد: کودک برای بقا به مراقب نیاز دارد و بر اساس اینکه این مراقب چقدر در دسترس، پاسخ‌گو و قابل‌پیش‌بینی است، تصویری درونی از خود و دیگران می‌سازد. سال ۱۹۸۷، سیندی هازان و فیلیپ شیور نشان دادند که همان سه سبک اصلی دلبستگی کودکی، یعنی ایمن، اجتنابی و اضطرابی، در عشق بزرگسالان هم دیده می‌شوند و فراوانی نسبی‌شان در بزرگسالی تقریباً شبیه کودکی است.</p><p>سایکولوژی تودی سبک‌های دلبستگی بزرگسالان را چنین توصیف می‌کند:</p><ul><li>ایمن: راحت با نزدیکی و تکیه کردن به دیگران.</li><li>اضطرابی (دل‌مشغول): نگرانی زیاد درباره‌ی رابطه و میل شدید به نزدیکی.</li><li>اجتنابی (انکاری): نگرانی کم، اما فاصله گرفتن از نزدیکی.</li><li>ترسان-اجتنابی: هم نگرانی زیاد و هم ترس از نزدیکی.</li></ul><p>نکته‌ی مهم این است که سبک دلبستگی سرنوشت نیست. فراتحلیلی بر پایه‌ی ۱۲۷ مقاله و بیش از ۲۱ هزار مورد نشان داد که ثبات دلبستگی از نوزادی تا اوایل بزرگسالی در حد متوسط است و در فاصله‌های بیش از پانزده سال، ثبات معناداری دیده نشد. یعنی تجربه‌های تازه می‌توانند سبک دلبستگی را تغییر دهند. پژوهشی روی ۱۷۲ زوج هم نشان داد که احساس امنیت دو همسر در طول زمان با هم تغییر می‌کند؛ رابطه‌ی امن، امنیت می‌سازد.</p><h2>الگوهای رایج سبک‌های ناایمن در رابطه</h2><ul><li>دنبال کردن و فرار: یکی برای نزدیکی می‌دود، دیگری عقب می‌کشد</li><li>نیاز مداوم به اطمینان و تأیید</li><li>حسادت و نگرانی شدید از رها شدن</li><li>سرکوب احساسات و ناراحتی از درخواست‌های عاطفی همسر</li><li>دوری گزیدن در لحظه‌های حساس، مثل دعوا یا بیماری</li><li>برداشت تهدیدآمیز از رفتارهای عادی، مثل دیر جواب دادن</li><li>کشش به آدم‌هایی که الگوی ناایمن را تقویت می‌کنند</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>سبک خودتان را بشناسید. دانستن اینکه واکنش‌هایتان از کجا می‌آید، کمک می‌کند آن‌ها را شخصی نکنید و به‌جای سرزنش خود یا همسر، الگو را ببینید.</li><li>چرخه را دشمن بدانید، نه همدیگر را. در بسیاری از زوج‌ها، مشکل اصلی چرخه‌ی «دنبال کردن و فرار» است. وقتی هر دو آن را ببینید، می‌توانید با هم علیه آن کار کنید.</li><li>نیازتان را مستقیم بگویید. اگر سبک اضطرابی دارید، به‌جای سرزنش، نیاز را بگویید: «وقتی دیر می‌کنی، نگران می‌شم. اگه یه پیام کوتاه بدی، خیلی آروم‌تر می‌شم.»</li><li>فاصله را اعلام کنید، نه فرار. اگر سبک اجتنابی دارید، به‌جای رفتن بی‌خبر، بگویید: «الان یه کم وقت لازم دارم آروم بشم. یه ساعت دیگه برمی‌گردم حرف بزنیم.» و برگردید.</li><li>آرام کردن خود را تمرین کنید. تنفس آهسته، نوشتن و ذهن‌آگاهی کمک می‌کنند در لحظه‌ی برانگیختگی، الگوی قدیمی را تکرار نکنید.</li><li>رابطه‌ی امن را تجربه کنید. رابطه با همسری پاسخ‌گو، دوستان قابل اعتماد یا رابطه‌ی درمانی، کم‌کم امنیت درونی می‌سازد.</li></ol><p>و نیلوفر و کیان؟ در جلسه‌های مشاوره، هر دو فهمیدند در چرخه‌ای گیر افتاده‌اند که هیچ‌کدام مقصرش نبودند: هرچه نیلوفر از ترس رها شدن دنبال می‌کرد، کیان از ترس خفگی بیشتر فرار می‌کرد. مشاور به آن‌ها کمک کرد قرارهای ساده‌ای بگذارند. کیان قول داد اگر دیر کند، پیام کوتاهی بدهد؛ نیلوفر قول داد اگر پیام رسید، دیگر زنگ نزند. وقتی دعوا داغ می‌شد، کیان یاد گرفت به‌جای رفتن، بگوید: «بیست دقیقه وقت می‌خوام، ولی برمی‌گردم.» نیلوفر هم یاد گرفت در این بیست دقیقه، به خودش یادآوری کند که «برمی‌گردد». بار اول، بیست دقیقه برای نیلوفر مثل بیست ساعت گذشت. اما کیان برگشت. و بار بعد، و بار بعد. چند ماه بعد، نیلوفر به مشاور گفت: «هنوز گاهی می‌ترسم. ولی دیگه اون ترس رئیس من نیست.»</p><h2>باورهای نادرست رایج درباره‌ی سبک‌های دلبستگی</h2><p>«سبک دلبستگی تا آخر عمر ثابت است.» پژوهش‌ها نشان می‌دهند تجربه‌های تازه و رابطه‌های امن می‌توانند آن را تغییر دهند.</p><p>«آدم‌های اضطرابی حسود و ضعیف‌اند.» سبک اضطرابی پاسخی آموخته به رابطه‌های ناپایدار گذشته است، نه نقص شخصیت.</p><p>«آدم‌های اجتنابی نمی‌توانند عاشق شوند.» آن‌ها هم دوست دارند و دوست داشته می‌شوند؛ فقط نزدیکی برایشان ترسناک‌تر است.</p><p>«دو نفر با سبک ناایمن نمی‌توانند رابطه‌ی خوبی بسازند.» با آگاهی و تلاش مشترک، بسیاری از این زوج‌ها رابطه‌ی امنی ساخته‌اند.</p><p>«همه چیز تقصیر پدر و مادر است.» تجربه‌های کودکی مهم‌اند، اما مسئولیت تغییر امروز با خود ماست.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر چرخه‌ی دنبال کردن و فرار، رابطه‌تان را فرسوده کرده، اگر ترس از رها شدن یا نزدیکی، زندگی عاطفی‌تان را مختل کرده، اگر رابطه‌هایتان مدام به پایان‌های شبیه هم می‌رسند، یا اگر پیش از ازدواج می‌خواهید الگوهای هم را بهتر بشناسید، کمک تخصصی بسیار مؤثر است. برای رزرو جلسه با روان‌شناسان مرکز مشاوره‌ی انتخاب بهتر با شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>بدترین سبک دلبستگی کدام است؟</h3><p>سبک «بد» یا «بدتر» وجود ندارد. هر سبک ناایمن، راهی برای کنار آمدن با تجربه‌های گذشته بوده است و می‌شود به سمت امنیت بیشتر حرکت کرد.</p><h3>آیا رابطه‌ی اضطرابی و اجتنابی محکوم به شکست است؟</h3><p>نه. این ترکیب رایج است و با شناخت چرخه، قرارهای روشن و گاهی زوج‌درمانی، می‌تواند به رابطه‌ای امن تبدیل شود.</p><h3>چطور سبک دلبستگی‌ام را بفهمم؟</h3><p>پرسشنامه‌های معتبر سبک دلبستگی و گفتگو با متخصص کمک می‌کنند تصویر دقیق‌تری از الگوی خود داشته باشید.</p><h2>جمع‌بندی</h2><p>سبک‌های دلبستگی الگوهایی‌اند که از رابطه‌های اولیه شکل گرفته‌اند و در عشق بزرگسالی تکرار می‌شوند. شناختن سبک خود و همسر، دیدن چرخه‌ی «دنبال کردن و فرار» و تمرین گفتن مستقیم نیازها، راه رسیدن به رابطه‌ای امن‌تر است. خبر خوب این است که امنیت، قابل یادگیری است.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/13/%D9%85%D9%82%DB%8C%D8%A7%D8%B3-%D8%B3%D8%A8%DA%A9-%D8%AF%D9%84%D8%A8%D8%B3%D8%AA%DA%AF%DB%8C-%DA%A9%D9%88%D9%84%DB%8C%D9%86%D8%B2-%D9%88-%D8%B1%DB%8C%D8%AF" target="_blank" rel="noopener">مقیاس سبک دلبستگی کولینز و رید</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/350/%D8%BA%D9%86%DB%8C-%D8%B3%D8%A7%D8%B2%DB%8C-%D8%B1%D9%88%D8%A7%D8%A8%D8%B7" target="_blank" rel="noopener">غنی سازی روابط</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6695/%D8%B9%D8%B4%D9%82_%D9%88_%D8%A7%D9%86%D9%82%D9%84%D8%A7%D8%A8_%D8%AF%D9%84%D8%A8%D8%B3%D8%AA%DA%AF%DB%8C" target="_blank" rel="noopener">عشق و انقلاب دلبستگی</a></p><p><a href="https://www.betterchoice.ir/fa/print/news/6688" target="_blank" rel="noopener">اضطراب روابط عاطفی: چگونه از این اضطراب عبور کنیم؟</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6760/%DB%B3_%D9%86%D8%B4%D8%A7%D9%86%D9%87_%D8%A7%D8%B3%D8%AA%D9%82%D9%84%D8%A7%D9%84_%D8%A7%D9%81%D8%B1%D8%A7%D8%B7%DB%8C_%DA%A9%D9%87_%D9%85%D8%A7%D9%86%D8%B9_%D9%88%D8%B1%D9%88%D8%AF_%D8%A8%D9%87_%D8%B1%D9%88%D8%A7%D8%A8%D8%B7_%D9%85%DB%8C%E2%80%8C%D8%B4%D9%88%D8%AF" target="_blank" rel="noopener">۳ نشانه استقلال افراطی که مانع ورود به روابط می‌شود</a></p></div>','["Hazan, C., &amp; Shaver, P. (1987). Romantic love conceptualized as an attachment process. Journal of Personality and Social Psychology, 52(3), 511–524. https://pubmed.ncbi.nlm.nih.gov/3572722/", "Hudson, N. W., Fraley, R. C., Brumbaugh, C. C., &amp; Vicary, A. M. (2014). Coregulation in romantic partners'' attachment styles: A longitudinal investigation. Personality and Social Psychology Bulletin, 40(7), 845–857. https://pubmed.ncbi.nlm.nih.gov/24743602/", "Pinquart, M., Feussner, C., &amp; Ahnert, L. (2013). Meta-analytic evidence for stability in attachments from infancy to early adulthood. Attachment &amp; Human Development, 15(2), 189–218. https://pubmed.ncbi.nlm.nih.gov/23210665/", "Psychology Today. Attachment. https://www.psychologytoday.com/us/basics/attachment"]'::jsonb,true,true),
('a10','فرسودگی شغلی: وقتی کار همه‌ی انرژی را می‌بلعد','همه‌ی ما روزهای خسته‌کننده در کار داریم. اما فرسودگی چیزی فراتر از خستگی است: حسی که حتی بعد از تعطیلات هم نمی‌رود، کاری که روزی با شوق انجامش می‌دادیم، حالا فقط باری سنگین است و این فکر که «دیگه هیچ‌چیزی ندارم که بدم». فرسودگی شغلی پدیده‌ای شناخته‌شده است که سازمان جهانی بهداشت هم آن را تعریف کرده است و اگر جدی گرفته نشود، به سلامت جسم، روان و رابطه‌ها آسیب می‌زند. این مقاله با قصه‌ی پرستاری شروع می‌شود که روزی عاشق کارش بود.','work',6,'تحریریهٔ مجله','شورای علمی انتخاب بهتر','۱۴۰۵/۰۸/۱۰','img/articles/a10-cover.jpg','img/articles/a10-thumb.jpg','<h2>قصه‌ی الهام: پرستاری که دیگر چیزی حس نمی‌کرد</h2><p>الهام سی‌وهشت سال دارد و سرپرستار بخش مراقبت‌های ویژه‌ی یک بیمارستان دولتی است. پانزده سال پیش، وقتی کارش را شروع کرد، عاشق شغلش بود. شب‌ها به بیمارانش فکر می‌کرد، برای خانواده‌هایشان وقت می‌گذاشت و همکارانش او را «فرشته‌ی بخش» صدا می‌زدند.</p><p>در سه سال گذشته، اما، چیزی عوض شده بود. بخش کمبود نیرو داشت و الهام هفته‌ای سه شیفت شب می‌ایستاد. کاغذبازی‌ها دو برابر شده بود. مدیریت جدید بیمارستان، بی‌آنکه نظر پرستارها را بپرسد، برنامه‌ها را عوض می‌کرد.</p><p>آن صبح، بعد از یک شیفت شب سخت، الهام در رختکن نشسته بود. یکی از بیمارانش، پیرمردی که دو هفته از او مراقبت کرده بود، شب قبل فوت کرده بود. الهام منتظر غم بود، اما چیزی حس نکرد. هیچ. فقط خستگی.</p><p>همین بی‌حسی ترساندش. با خودش فکر کرد: «من کی این‌قدر سرد شدم؟»</p><p>چند هفته بود نشانه‌ها جمع شده بودند. صبح‌ها، پیش از رفتن به بیمارستان، دل‌درد داشت. در خانه، با کوچک‌ترین سروصدای بچه‌هایش منفجر می‌شد. شب‌ها، با وجود خستگی، خوابش نمی‌برد. حتی وقتی خانواده‌ی بیماری از او تشکر می‌کرد، در دلش فکر می‌کرد: «فایده‌ای نداره. هر کاری کنیم، باز کم میاد.»</p><p>آن روز، در راهروی بخش، دستیار تازه‌کاری سؤال ساده‌ای پرسید. الهام با تندی جواب داد: «مگه خودت بلد نیستی؟» دختر جوان سرخ شد و رفت. الهام همان لحظه پشیمان شد. این اصلاً شبیه او نبود. پانزده سال پیش، خودش همان دستیار تازه‌کار بود و سرپرستار مهربانی ساعت‌ها کنارش ایستاده بود تا کار با دستگاه تنفس را یادش بدهد.</p><p>شب، همسرش، رضا، دید که الهام روی مبل نشسته و به دیوار خیره مانده است. «الهام، چند وقته حالت خوب نیست. چی شده؟»</p><p>الهام اشک ریخت. «رضا، من دیگه نمی‌تونم. نه اینکه کار سخت باشه؛ همیشه سخت بوده. انگار ته کشیدم. حتی دیگه برام مهم نیست. و این از همه بدتره.»</p><p>رضا گفت: «شاید وقتشه به جای اینکه بیشتر تحمل کنی، کمک بگیری.»</p><p>الهام سر تکان داد. فردا، برای اولین بار در پانزده سال، به‌جای اضافه‌کاری، مرخصی گرفت و وقت مشاوره رزرو کرد.</p><h2>از کجا بفهمم دچار فرسودگی شغلی شده‌ام؟ چند پرسش برای خودسنجی</h2><p>این پرسش‌ها ابزار تشخیص نیستند؛ فقط کمک می‌کنند وضعیت خودتان را بهتر ببینید.</p><ol><li>آیا بیشتر روزها، حتی بعد از استراحت، احساس خستگی و ته کشیدن می‌کنید؟</li><li>آیا نسبت به کار، همکاران یا مراجعانتان بدبین، بی‌تفاوت یا سرد شده‌اید؟</li><li>آیا احساس می‌کنید دیگر کارتان را به خوبی گذشته انجام نمی‌دهید؟</li><li>آیا صبح‌ها با احساس دلهره یا بی‌میلی شدید سر کار می‌روید؟</li><li>آیا خوابتان به هم ریخته یا نشانه‌های بدنی مثل سردرد و دل‌درد دارید؟</li><li>آیا در خانه زودرنج‌تر و کم‌حوصله‌تر شده‌اید؟</li></ol><h2>فرسودگی شغلی چیست و چرا پیش می‌آید؟</h2><p>سازمان جهانی بهداشت در یازدهمین ویرایش طبقه‌بندی بین‌المللی بیماری‌ها، فرسودگی شغلی را سندرمی تعریف کرده که از استرس مزمن محل کار، که به‌خوبی مدیریت نشده، پدید می‌آید. این سازمان تأکید می‌کند که فرسودگی شغلی یک «بیماری» نیست، بلکه پدیده‌ای شغلی است و فقط در زمینه‌ی کار به کار می‌رود. سه بعد اصلی آن عبارت‌اند از: احساس ته کشیدن انرژی یا خستگی، فاصله‌ی ذهنی از شغل یا بدبینی نسبت به آن، و کاهش کارآمدی حرفه‌ای.</p><p>کریستینا مسلش، پیشگام پژوهش در این حوزه، و مایکل لایتر در مروری جامع توضیح می‌دهند که فرسودگی پاسخی طولانی به عوامل استرس‌زای مزمن بین‌فردی در کار است و بیشتر از عدم تناسب میان فرد و محیط کار می‌آید؛ از جمله در حجم کار، میزان کنترل، پاداش، حس همبستگی، انصاف و ارزش‌ها. یعنی فرسودگی فقط مشکل فرد نیست؛ محیط کار هم در آن نقش جدی دارد.</p><h2>نشانه‌های رایج فرسودگی شغلی</h2><ul><li>خستگی جسمی و روانی مداوم که با استراحت برطرف نمی‌شود</li><li>بدبینی، بی‌تفاوتی و فاصله‌ی عاطفی از کار و آدم‌ها</li><li>احساس ناکارآمدی و بی‌فایده بودن تلاش‌ها</li><li>تحریک‌پذیری و کم‌حوصلگی در کار و خانه</li><li>مشکلات خواب، سردرد، دل‌درد و بیماری‌های مکرر</li><li>کاهش تمرکز و افت عملکرد</li><li>دلهره پیش از رفتن به کار</li><li>در مشاغل یاری‌رسان، کم شدن همدلی با مراجعان</li></ul><h2>چه کاری از دستتان برمی‌آید؟</h2><ol><li>نشانه‌ها را جدی بگیرید. فرسودگی معمولاً آرام و تدریجی می‌آید. آدم‌های پرتلاش اغلب به‌جای کند کردن، بیشتر فشار می‌آورند. توقف و دیدن نشانه‌ها، اولین قدم است.</li><li>مرز میان کار و زندگی بکشید. ساعت مشخصی برای پایان کار بگذارید، بعد از آن ایمیل و پیام کاری را چک نکنید و استراحت‌های کوتاه در طول روز داشته باشید.</li><li>منبع فشار را شناسایی کنید. از خود بپرسید: مشکل حجم کار است، نبود کنترل، بی‌انصافی، کم بودن قدردانی یا تعارض با ارزش‌هایم؟ هر کدام راه‌حل متفاوتی دارد.</li><li>گفتگو کنید و تغییر بخواهید. با مدیر یا همکاران درباره‌ی حجم کار، تقسیم وظایف یا انعطاف در برنامه حرف بزنید. پیش از تصمیم به ترک کار، امکان تغییر در همان جا را بسنجید.</li><li>منبع‌های انرژی بیرون از کار را برگردانید. ورزش، خواب کافی، سرگرمی، دوستان و خانواده، باتری‌هایی‌اند که فرسودگی آن‌ها را خالی کرده است.</li><li>معنا را دوباره پیدا کنید. یادآوری اینکه چرا این کار را انتخاب کرده‌اید، یا پیدا کردن بخشی از کار که هنوز برایتان معنادار است، به بازگشت انگیزه کمک می‌کند.</li></ol><p>و الهام؟ در جلسه‌های مشاوره، الهام فهمید که بی‌حسی‌اش نشانه‌ی سنگدلی نیست، بلکه نشانه‌ی فرسودگی است؛ ذهنی که برای محافظت از خود، خاموش شده بود. با کمک روان‌شناسش، فهرستی از منبع‌های فشار نوشت و با مدیر بیمارستان درباره‌ی شیفت‌های شب حرف زد. شیفت‌های شبش به یکی در هفته کم شد. الهام دوباره پیاده‌روی صبحگاهی‌اش را شروع کرد و قرار گذاشت در خانه، تا ساعت نه شب، گوشی‌اش را کنار بگذارد. چند ماه بعد، بیمار جوانی که از کما بیرون آمده بود، دستش را گرفت و تشکر کرد. الهام گرمای اشک را روی گونه‌اش حس کرد. شب، به رضا گفت: «امروز دوباره یه چیزی حس کردم. فکر کنم دارم برمی‌گردم.»</p><h2>باورهای نادرست رایج درباره‌ی فرسودگی شغلی</h2><p>«فرسودگی یعنی تنبلی یا ضعف.» فرسودگی اغلب سراغ پرتلاش‌ترین و متعهدترین آدم‌ها می‌آید.</p><p>«یک تعطیلات خوب، فرسودگی را درمان می‌کند.» استراحت کمک می‌کند، اما اگر شرایط کار تغییر نکند، فرسودگی برمی‌گردد.</p><p>«فرسودگی فقط مال مشاغل سخت است.» هر شغلی که در آن عدم تناسب میان فرد و محیط کار باشد، می‌تواند به فرسودگی برسد.</p><p>«فرسودگی همان افسردگی است.» این دو هم‌پوشانی دارند، اما فرسودگی به زمینه‌ی کار مربوط است. البته فرسودگی درمان‌نشده می‌تواند به افسردگی برسد.</p><p>«تنها راه، ترک کار است.» بسیاری از افراد با تغییر شرایط کار، مرزگذاری و حمایت، بدون ترک شغل بهبود یافته‌اند.</p><h2>چه وقت سراغ متخصص برویم؟</h2><p>اگر خستگی و بی‌انگیزگی هفته‌هاست ادامه دارد، اگر نشانه‌های بدنی، بی‌خوابی یا غم عمیق پیدا کرده‌اید، اگر رابطه‌هایتان آسیب دیده، یا اگر به مصرف مواد یا الکل برای کنار آمدن روی آورده‌اید، وقت کمک گرفتن است. برای رزرو جلسه با روان‌شناسان مرکز مشاوره‌ی انتخاب بهتر با شماره‌ی ۰۹۱۹۸۰۱۰۰۸۰ تماس بگیرید.</p><h2>پرسش‌های پرتکرار</h2><h3>فرق استرس شغلی با فرسودگی شغلی چیست؟</h3><p>استرس معمولاً با «بیش از حد» همراه است: کار زیاد، فشار زیاد. فرسودگی با «کمتر از حد» همراه است: انرژی ته کشیده، انگیزه‌ی کم و احساس پوچی.</p><h3>بهبود از فرسودگی شغلی چقدر طول می‌کشد؟</h3><p>به شدت فرسودگی و امکان تغییر شرایط بستگی دارد. برای برخی چند هفته و برای برخی چند ماه.</p><h3>آیا فرسودگی شغلی بیماری است؟</h3><p>سازمان جهانی بهداشت آن را یک بیماری نمی‌داند، بلکه پدیده‌ای شغلی می‌شمارد که می‌تواند بر سلامت اثر بگذارد.</p><h2>جمع‌بندی</h2><p>فرسودگی شغلی سندرمی است که از استرس مزمن و مدیریت‌نشده‌ی کار می‌آید و با خستگی، بدبینی و احساس ناکارآمدی شناخته می‌شود. دیدن نشانه‌ها، مرزگذاری، شناسایی منبع فشار، گفتگو برای تغییر و برگرداندن منبع‌های انرژی و معنا، راه بازگشت است. فرسودگی نشانه‌ی ضعف نیست؛ پیامی است که می‌گوید چیزی باید تغییر کند.</p><h2 class="next">قدم بعدی شما</h2><div class="next-box"><p>📝 پرسشنامه‌ی مرتبط: <a href="https://www.betterchoice.ir/fa/qdetail/101/%D9%81%D8%B1%D8%B3%D9%88%D8%AF%DA%AF%DB%8C-%D8%B4%D8%BA%D9%84%DB%8C-%DA%AF%D9%84%D8%AF%D8%A7%D8%B1%D8%AF" target="_blank" rel="noopener">فرسودگی شغلی گلدارد</a>، <a href="https://www.betterchoice.ir/fa/qdetail/100/%D9%BE%D8%B1%D8%B3%D8%B4%D9%86%D8%A7%D9%85%D9%87-%D8%A7%D8%B3%D8%AA%D8%B1%D8%B3-%D8%B4%D8%BA%D9%84%DB%8C-%D8%A7%D8%B3%D8%AA%D8%A7%DB%8C%D9%86%D9%85%D8%AA%D8%B2" target="_blank" rel="noopener">پرسشنامه استرس شغلی استاینمتز</a></p><p>💬 رزرو جلسه‌ی مشاوره‌ی فردی: ۰۹۱۹۸۰۱۰۰۸۰</p><p>🎓 دوره‌ی آموزشی موسسه انتخاب بهتر: <a href="https://www.betterchoice.ir/fa/edu/954/%D8%AA%D8%B9%D8%A7%D8%AF%D9%84-%D8%AF%D8%B1-%D8%B2%D9%86%D8%AF%DA%AF%DB%8C" target="_blank" rel="noopener">تعادل در زندگی</a></p><p>📖 بیشتر بخوانید:</p><p><a href="https://www.betterchoice.ir/fa/ndt/6768/%D8%A8%D8%B1%D8%A7%DB%8C_%D8%AF%D8%A7%D8%B4%D8%AA%D9%86_%D8%B2%D9%86%D8%AF%DA%AF%DB%8C_%D9%87%D8%AF%D9%81%D9%85%D9%86%D8%AF_%D9%84%D8%A7%D8%B2%D9%85_%D9%86%DB%8C%D8%B3%D8%AA_%D8%B9%D8%A7%D8%B4%D9%82_%D8%B4%D8%BA%D9%84%D8%AA%D8%A7%D9%86_%D8%A8%D8%A7%D8%B4%DB%8C%D8%AF" target="_blank" rel="noopener">برای داشتن زندگی هدفمند، لازم نیست عاشق شغلتان باشید</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6738/%DB%B5_%D9%82%D8%AF%D9%85_%D8%A8%D8%B1%D8%A7%DB%8C_%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA_%D8%A8%D9%87%D8%AA%D8%B1_%DA%AF%D9%81%D8%AA%DA%AF%D9%88%D9%87%D8%A7%DB%8C_%D8%AF%D8%B4%D9%88%D8%A7%D8%B1_%D8%A8%D8%A7_%D9%87%D9%85%DA%A9%D8%A7%D8%B1%D8%A7%D9%86" target="_blank" rel="noopener">۵ قدم برای مدیریت بهتر گفتگوهای دشوار با همکاران</a></p><p><a href="https://www.betterchoice.ir/fa/ndt/6751/%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA_%D9%87%DB%8C%D8%AC%D8%A7%D9%86%E2%80%8C%D9%87%D8%A7%DB%8C_%D8%B7%D8%A7%D9%82%D8%AA%E2%80%8C%D9%81%D8%B1%D8%B3%D8%A7" target="_blank" rel="noopener">مدیریت هیجان‌های طاقت‌فرسا</a></p></div>','["Maslach, C., &amp; Leiter, M. P. (2016). Understanding the burnout experience: Recent research and its implications for psychiatry. World Psychiatry, 15(2), 103–111. https://pmc.ncbi.nlm.nih.gov/articles/PMC4911781/", "Psychology Today. Burnout. https://www.psychologytoday.com/us/basics/burnout", "World Health Organization. (2019, May 28). Burn-out an \"occupational phenomenon\": International Classification of Diseases [News release]. https://www.who.int/news/item/28-05-2019-burn-out-an-occupational-phenomenon-international-classification-of-diseases"]'::jsonb,false,true)
